return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'sw','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-29T14:57:34+00:00','po-revision-date'=>'2026-07-05 23:15+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Njia za lugha nyingi, SEO kamili ya lugha nyingi (hreflang, Open Graph, Schema.org, ramani ya tovuti), na zana za AI za maudhui kwa WordPress. Utambuzi wa lugha, njia za URL, tafsiri, uzalishaji wa maudhui, na safu kamili ya SEO — hakuna programu-jalizi ya msaidizi inayohitajika.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Tafsiri','Lingua Forge — Quick Translate'=>'Lingua Forge — Tafsiri Haraka','Informative'=>'Taarifa','Persuasive'=>'Ushawishi','Storytelling'=>'Hadithi','Technical'=>'Kitaaluma','Conversational'=>' Mazungumzo','Translate missing'=>'Tafsiri isiyokamilika','%d comment translation created.'=>'%d tafsiri ya maoni iliyoundwa.' . "\0" . '%d tafsiri za maoni zimeundwa.','%d pair could not be translated yet (e.g. a nested reply waiting on its parent, or a language currently in cooldown after repeated failures).'=>'%d vipande haviwezi kutafsiriwa bado (mfano, jibu lililokuwa la ndani linangoja mzazi wake, au lugha ambayo kwa sasa iko katika kupumzika baada ya kushindwa mara nyingi).' . "\0" . '%d vipande haviwezi kutafsiriwa bado (mfano, majibu yaliyo ndani yanayoangoja mzazi wao, au lugha ambayo kwa sasa iko katika kupumzika baada ya kushindwa mara nyingi).','Permission denied.'=>'Ruhusa imekatwa.','Cannot determine target language from slug.'=>'Haiwezi kubaini lugha lengwa kutoka kwa slug.','Invalid post type.'=>'Aina ya chapisho si sahihi.','Invalid or primary language.'=>'Lugha si sahihi au ni kuu.','Template not found or not stored in the database.'=>'Kiolezo hakipatikani au hakijahifadhiwa kwenye hifadhidata.','Template has no content.'=>'Kiolezo hakina maudhui.','No internal links found to update.'=>'Hakuna viungo vya ndani vilivyopatikana vya kusasisha.','%d link updated.'=>'%d kiungo kimesasishwa.' . "\0" . '%d viungo vimesasishwa.','No language-specific template parts found to map.'=>'Hakuna sehemu za kiolezo zinazohitajika kubadilishwa ili kuoanisha.','No template part references needed updating.'=>'Hakuna marejeo ya sehemu za kiolezo zinazohitajika kusasishwa.','%d part reference updated.'=>'%d marejeo ya sehemu yamesasishwa.' . "\0" . '%d marejeo ya sehemu yamesasishwa.','Invalid language.'=>'Lugha si sahihi.','Template part not found or not stored in the database.'=>'Sehemu ya kiolezo hakipatikani au hakijahifadhiwa kwenye hifadhidata.','Template part has no content.'=>'Sehemu ya kiolezo hakina maudhui.','No navigation references needed updating.'=>'Hakuna marejeo ya urambazaji yanayohitajika kusasishwa.','%d navigation reference updated.'=>'%d marejeo ya urambazaji yamesasishwa.' . "\0" . '%d marejeo ya urambazaji yamesasishwa.','No AI provider configured.'=>'Mtoa huduma wa AI hajaanzishwa.','Missing pattern name or language.'=>'Jina la muundo au lugha inakosekana.','Pattern not found.'=>'Muundo haujapatikana.','Pattern has no content to translate.'=>'Muundo haujashikilia maudhui ya kutafsiriwa.','AI provider returned an empty response.'=>'Mtoa huduma wa AI alirudisha majibu tupu.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Muundo umetafsiriwa na kuhifadhiwa. Nakili maudhui kwenye chapisho lako la CPT kupitia mhariri wa kiolezo au tumia kama mwanzo wa Kiolezo kinachoweza kutumika tena.','%d template repaired.'=>'%d templates zilirekebishwa.' . "\0" . '%d templates zilirekebishwa.','All template metadata is already up to date.'=>'Metadata ya template yote tayari imesasishwa.','Invalid template type.'=>'Aina ya kiolezo si sahihi.','Template "%s" already exists.'=>'Kiolezo "%s" tayari kipo.','Fix Links'=>'Rekebisha Viungo','Fix Parts'=>'Rekebisha Sehemu','Re-create'=>'Tengeneza upya','"%s" recreated.'=>'"%s" imetengenezwa upya.','"%s" created.'=>'"%s" imetengenezwa.','Invalid template part.'=>'Sehemu ya kiolezo si sahihi.','Template part "%s" already exists.'=>'Sehemu ya kiolezo "%s" tayari kipo.','Fix Nav'=>'Rekebisha Urambazaji','"%1$s" recreated. %2$d template updated.'=>'"%1$s" imetengenezwa upya. Kiolezo %2$d kilichohadithwa.' . "\0" . '"%1$s" imetengenezwa upya. Kiolezo %2$d kilizohadithwa.','"%1$s" created. %2$d template updated.'=>'"%1$s" imetengenezwa. %2$d kiolezo kimesasishwa.' . "\0" . '"%1$s" imetengenezwa. %2$d kiolezo kimesasishwa.','Page'=>'Ukurasa','Single'=>'Moja','Search'=>'Tafuta','Search Results'=>'Matokeo ya Utafutaji','Archive'=>'Makala','Front Page'=>'Ukurasa wa Mbele','Blog Home'=>'Nyumbani kwa Blogu','Single: %s'=>'Moja: %s','Single %s'=>'Moja %s','Archive: %s'=>'Hifadhi: %s','%s Archive'=>'Hifadhi %s','No source content found to translate.'=>'Hakuna maudhui ya chanzo yaliyopatikana ya kutafsiri.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Imetafsiriwa. Pitia kwenye Mhariri wa Tovuti — viungo vya ndani, URLs za urambazaji, na majina ya kiolezo hayasaswi kiotomatiki.','Navigation not found.'=>'Uelekeo haujapatikana.','Navigation has no content to translate.'=>'Uelekeo haujakuwa na maudhui ya kutafsiri.','"%1$s %2$s" saved.'=>'"%1$s %2$s" imehifadhiwa.','SEO Analysis'=>'Uchambuzi wa SEO','Profile'=>'Wasifu','Details ↗'=>'Maelezo ↗','/ 100'=>'/ 100','Overall SEO score'=>'Alama ya jumla ya SEO','Metric'=>'Kiwango','Finding'=>'Utafutaji','Title'=>'Kichwa','Meta description'=>'Maelezo ya meta','Word count'=>'Idadi ya maneno','Reading time'=>'Muda wa kusoma','Headings'=>'Vichwa vya habari','Images'=>'Picha','Links'=>'Viungo','AI Recommendations'=>'Mapendekezo ya AI','Run AI Analysis'=>'Endesha Uchanganuzi wa AI','Analyzing…'=>'Inachambua…','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Sanidi mtoa huduma wa AI katika Settings → API Keys ili kuwezesha mapendekezo yanayotegemea AI.','AI analysis failed. Please try again.'=>'Uchambuzi wa AI umeshindwa. Tafadhali jaribu tena.','Suggested title'=>'Kichwa cha pendekezo','Suggested meta description'=>'Maelezo ya meta yaliyopendekezwa','Loaded from cache.'=>'Imepakuliwa kutoka kwa cache.','↺ Refresh AI Analysis'=>'↺ Sasisha Uchambuzi wa AI','Analyse…'=>'Chambua…','Analysis request failed. Please try again.'=>'Ombi la uchambuzi limekosa mafanikio. Tafadhali jaribu tena.','No translation found — analyzed the source language version.'=>'Hakuna tafsiri iliyopatikana — ilitathmini toleo la lugha asili.','Translate page…'=>'Tafsiri ukurasa…','Generate content…'=>'Tengeneza maudhui…','AI Behaviour Preset'=>'Mipangilio ya Tabia za AI','Custom'=>'Maendeleo Maalum','Global default (%s)'=>'Chaguo-msingi duniani kote (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Inabadilisha mipangilio ya AI kwa Tafsiri na Uundaji wa Maudhui kwenye ukurasa huu. Maagizo ya maoni maalum ya tovuti yote (Mipangilio → Tabia) yanajumuishwa kila wakati kwenye kila ombi bila kujali chaguo hili.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Inabadilisha mipangilio ya AI kwa Tafsiri na Uundaji wa Maudhui kwenye ukurasa huu. Vipengele vingine vyote vinatumia mipangilio ya jumla kila wakati.','Close'=>'Funga','From'=>'Kutoka','Retranslate'=>'Tafsiri tena','Retranslate every other language version from this post. Creates any that are missing and overwrites any that already exist — including the primary language, if this post is a translation.'=>'Tafsiri kila toleo jingine la lugha kutoka kwenye chapisho hili. Hutengeneza zile zenye upungufu na kuandika upya zile zilizopo tayari — ikiwemo lugha ya msingi, ikiwa chapisho hili ni tafsiri.','Sync'=>'Synchronize','Reassign the correct language-specific template to every existing translation of this post. No AI call and no content changes — free and safe to run any time.'=>'Kamatia kiolezo sahihi kinachohusiana na lugha kwa kila tafsiri iliyopo ya chapisho hili. Hakuna simu ya AI wala mabadiliko ya maudhui — bure na salama kuendeshwa wakati wowote.','Template Sync — reassign templates for every translation'=>'Synchronize Kiolezo — kamatia kiolezo kwa kila tafsiri','TS'=>'SK','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Alama ya SEO ya mwisho kwa kanuni. Endesha uchambuzi katika Usanidi → SEO → Uchambuzi ili kusasisha.','Translating…'=>'Inatafsiri…','Retranslating…'=>'Inatafsiri tena…','Syncing…'=>'Inakamatia…','This retranslates every other language version of this post from this one — creating any that are missing and overwriting any that already exist (including the primary language, if this post is a translation). This cannot be undone. Continue?'=>'Hii inatafsiri kila toleo jingine la lugha ya chapisho hili kutoka kwa hili — hutengeneza zile zenye upungufu na kuandika upya zile zilizopo (ikiwemo lugha ya msingi, ikiwa chapisho hili ni tafsiri). Haiwezi kuseswa. Kuendelea?','Syncing templates…'=>'Inakamatia kiolezo…','✓ Done'=>'✓ Imekamilika','Error'=>'Hitilafu','Navigation posts are translated via the Router tab, not this button.'=>'Maandishi ya urambazaji yanatafsiriwa kupitia kichupo cha Router, si kitufe hiki.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Kuunda tafsiri za aina ya chapisho "%s" kunahitaji muunganisho hai. Tafadhali hakikisha muunganisho unaohitajika umewekwa na kufanya kazi.','No %s version found in this translation group.'=>'Hakuna toleo la %s lililopatikana katika kundi hili la tafsiri.','Sync from a secondary-language WooCommerce product is disabled by default, since it would overwrite the primary product. Enable it in Settings → Behavior → WooCommerce if you want a translation to be able to become the new source content.'=>'Synchronize kutoka kwa bidhaa ya WooCommerce ya lugha ya upili imezuiwa kwa chaguo-msingi, kwa sababu ingeinua bidhaa ya msingi. Amilisha katika Mipangilio → Tabia → WooCommerce ikiwa unataka tafsiri iweze kuwa chanzo kipya cha maudhui.','Sync from a secondary-language post is disabled by default, since it would overwrite the primary post. Enable it in Settings → Behavior → Sync if you want a translation to be able to become the new source content.'=>'Synchronize kutoka kwa chapisho cha lugha ya upili imezuiwa kwa chaguo-msingi, kwa sababu ingeinua chapisho cha msingi. Amilisha katika Mipangilio → Tabia → Synchronize ikiwa unataka tafsiri iweze kuwa chanzo kipya cha maudhui.','Skipped — you do not have permission to edit the existing translation.'=>'Iliruka — huna ruhusa ya kuhariri tafsiri iliyopo.','Creating translations for post type "%s" requires an active integration.'=>'Kutengeneza tafsiri kwa aina ya chapisho "%s" kunahitaji ujumuishaji wenye kazi.','Template Sync can only be run from the primary/source-language post.'=>'Synchronize Kiolezo inaweza kuendeshwa tu kutoka kwa chapisho cha lugha ya msingi/chanzo.','Skipped — you do not have permission to edit this translation.'=>'Iliruka — huna ruhusa ya kuhariri tafsiri hii.','Translation Caching'=>'Kuhifadhi Kumbukumbu za Tafsiri','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge hutumia safu mbili za cache huru ili kuepuka kuita API za AI mara kwa mara. Tumia vivinjari hapa chini kuangalia na kusimamia kila moja.','API Response Cache'=>'Cache ya Majibu ya API','Translation Memory'=>'Kumbukumbu ya Tafsiri','(disabled)'=>'(imezimwa)','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Kahesheni ya kila chapisho kwa tafsiri zinazotengenezwa na AI, maelezo ya meta, muhtasari, na maudhui. Ingizo huondolewa kiotomatiki wakati maudhui au mtoa huduma/model wa AI unabadilika.','Enable API response caching'=>'Wezesha kuhifadhi majibu ya API','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'Kumbukumbu ya Majibu ya API hifadhi matokeo ya awali ya kila ombi la AI — tafsiri, maelezo ya meta, muhtasari, na uundaji wa maudhui — kwa kufuata hash ya maingizo (maudhui, jozi la lugha, mtoa huduma, mfano). Zima wakati wa kurekebisha maombi au unapo hitaji kila ombi lifikie mtoa huduma wa AI. Kuzima hakuhifadhi ingizo zilizohifadhiwa — kuzirudisha tena kunarudisha zile zilizohifadhiwa.','Save'=>'Hifadhi','Cached API responses'=>'Majibu ya API yaliyohifadhiwa','API calls saved by cache'=>'Vito vya API vilivyohifadhiwa na cache','(avg %.1f hits/entry)'=>'(wastani %.1f hits/kuingia)','Oldest cached response'=>'Majibu ya zamani zaidi yaliyohifadhiwa','Most recent cached response'=>'Majibu ya hivi karibuni yaliyohifadhiwa','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Futa matokeo yote ya AI yaliyohifadhiwa? Maombi yajayo yataanzisha wito mpya wa API hadi cache itakapojengwa upya.','Clear API Response Cache'=>'Futa Cache ya Majibu ya API','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Hifadhi ya tafsiri ya kiwango cha block inayoshirikiwa kati ya machapisho. Wakati imewezeshwa, blocks zinazofanana (alama sawa, jozi ya lugha, na kamusi) zinatumikia kutoka kwenye kumbukumbu badala ya kuita AI tena. Mabadiliko ya Kamusi na mabadiliko ya preset ya Uzingatiaji hufuta moja kwa moja tafsiri zilizohifadhiwa.','Enable block-level translation cache reuse across posts'=>'Wezesha upyaji wa hifadhi ya tafsiri kwenye block kwa posts','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Kwa sasa inakosewa kwa posts zinazotumia vigezo vya placeholder vya block-comment (wp:details fields za muhtasari, n.k.) — zinapita kwa njia ya tafsiri ya wito mmoja iliyopo.','Cached block translations'=>'Tafsiri za blokii zilizohifadhiwa','Block translation reuses'=>'Matumizi ya upya wa tafsiri za blok','(avg %.1f hits/block)'=>'(avg %.1f mafanikio/kipande)','Oldest cached block'=>'Blokii ya zamani zaidi iliyohifadhiwa','Most recent cached block'=>'Blokii ya hivi karibuni iliyohifadhiwa','Approximate size'=>'Ukubwa wa takriban','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Futa Kumbukumbu ya Tafsiri yote? Tafsiri za baadaye zitajenga tena cache wanapozalishwa.','Clear Translation Memory'=>'Futa Kumbukumbu ya Tafsiri','API Response Cache setting saved.'=>'Mipangilio ya Hifadhi ya Majibu ya API imehifadhiwa.','Translation Memory setting saved.'=>'Mipangilio ya Kumbukumbu ya Tafsiri imesimama.','AI cache cleared. %d entry was removed.'=>'Cache ya AI imefutwa. Kipengee %d kiliondolewa.' . "\0" . 'Cache ya AI imefutwa. Vipengee %d vimeondolewa.','Translation Memory cleared. %d cached block was removed.'=>'Kumbukumbu ya Tafsiri imefutwa. Kipande cha cache %d kiliondolewa.' . "\0" . 'Kumbukumbu ya Tafsiri imefutwa. Vipande %d vya cache vimeondolewa.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge ni suluhisho kamili la SEO lenye lugha nyingi. Hakuna plugin ya SEO ya ziada inayohitajika.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Ikiwa una programu-jalizi ya SEO ya jumla iliyowekwa, jopo hili linaonyesha jinsi LF inavyobadilika ili kuepuka matokeo ya kurudiwa. Lengo ni kuepuka migongano — si ushirikiano. LF daima hutoa safu ya SEO ya lugha nyingi (hreflang, og:locale, inLanguage schema) inayohitaji ujuzi wa usanidi wa mwelekeo wa lugha wa LF ili kuzalisha kwa usahihi.','Installed SEO plugins'=>'Programu-jalizi za SEO zilizowekwa','Plugin'=>'Programu-jalizi','Status'=>'Hali','✓ Active'=>'✓ Imo','— Not detected'=>'— Haijapatikana','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Hakuna plugins za SEO zinazopingana zilizogunduliwa. Lingua Forge inashughulikia matokeo yote ya SEO kwa uhuru.','What LF provides — and collision avoidance'=>'Kile LF hutoa — na kuepuka migongano','Feature'=>'Kipengele','LF provides'=>'LF hutoa','When another SEO plugin is installed'=>'Wakati plugin nyingine ya SEO imewekwa','Hreflang'=>'Hreflang','Disabled (by setting)'=>'Imelazimishwa (kwa kuweka)','✓ LF outputs — plugin hreflang suppressed'=>'✓ Matokeo ya LF — programu-jalizi hreflang imezuiwa','✓ LF outputs'=>'✓ Matokeo ya LF','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF hutoa hreflang sahihi kwa kila lugha iliyowekwa, ikiwa ni pamoja na x-default. Vichungi vya SEO vya jumla havina ufikiaji wa usanidi wa LF routing na vingezalisha hreflang kulingana na dhihaka zisizo sahihi za URL. LF huzuia matokeo yao kupitia kichujio ili kuzuia migongano.','Suppressed: %s.'=>'Imesimamishwa: %s.','Open Graph'=>'Open Graph','Disabled (mode setting)'=>'Imelazimishwa (uwezo wa mode)','→ Locale tags only — deferring base OG to plugin'=>'→ Lebo za eneo pekee — kuahirisha OG msingi kwa programu-jalizi','→ Locale tags only (manual setting)'=>'→ Lebo za eneo pekee (uwekaji wa mikono)','✓ LF outputs full OG + Twitter Cards'=>'✓ Matokeo ya LF OG kamili + Kadi za Twitter','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF daima huongeza og:locale na og:locale:alternate — ishara za lugha nyingi ambazo programu-jalizi haiwezi kuzalisha kwa usahihi. Kwa seti ya OG ya msingi (og:title, og:description, og:image), LF huitoa wakati hakuna programu-jalizi nyingine. Wakati programu-jalizi ya SEO imewekwa, LF huacha seti ya msingi ili kuepuka lebo za kurudiwa — si kwa sababu programu-jalizi ni "bora", bali kwa sababu kurudiwa hakutoa thamani.','Schema.org JSON-LD'=>'JSON-LD ya Schema.org','— Deferred to plugin'=>'— Imesogezwa kwa plugin','✓ LF outputs Article / WebPage / WebSite'=>'✓ Matokeo ya LF Article / WebPage / WebSite','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF hutoa JSON-LD yenye lugha nyingi na maelezo ya inLanguage yaliyoshikamana na usanidi wa routing wa lugha. Wakati plugin ya SEO imewekwa, LF huzimisha schema yake kabisa: michoro ya JSON-LD iliyojirudia huleta makosa ya uthibitishaji na hakuna njia safi ya kuongezea michoro iliyopo.','XML Sitemap'=>'Ramani ya XML','✓ Active at /lf-sitemap.xml'=>'✓ Imo kwenye /lf-sitemap.xml','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF huunda ramani yake ya tovuti yenye viungo vya xhtml:link kwa vikundi vyote vya tafsiri. Wakati programu-jalizi ya SEO imewekwa, huunda ramani tofauti — zote zinashirikiana kwa uhuru. Wasilisha zote kwa Google Search Console: ramani ya tovuti ya programu-jalizi ya SEO kwa ugunduzi wa maudhui, ramani ya tovuti ya LF kwa ishara za uhusiano wa lugha.','Canonical tag'=>' Lebo la Canonical','✓ WP canonical replaced (self-referencing)'=>'✓ WP imetoa nafasi ya canonical (inarejelea yenyewe)','WP core canonical active (hreflang disabled)'=>'Canonical ya msingi ya WP iko hai (hreflang imezimwa)','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'LF huondoa tagi ya canonical ya msingi ya WordPress na kuibadilisha na canonical inayojielekeza yenye kuelekeza kwenye URL sahihi yenye mwelekeo wa lugha. Wakati kiambatishi cha SEO cha mtu wa tatu (Yoast, Rank Math, AIOSEO, SEOPress) kinashikilia, LF huachilia usimamizi wa canonical kwa kiambatishi hicho kikamilifu.','Legacy lf-social-share mu-plugin'=>'Mu-plugin wa zamani wa lf-social-share','The lf-social-share mu-plugin is active.'=>'Mu- plugin wa lf-social-share ni hai.','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Modules za Kushiriki Kijamii na Open Graph zilizojengwa ndani ya Lingua Forge zinashughulikia kazi zote zinazotolewa na mu-plugin, pamoja na msaada wa og:locale wa lugha nyingi. Unaweza kuzima salama mu-plugin.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Vichwa vya OG/Twitter Card: vinashughulikiwa na moduli ya Open Graph ya LF (SEO → Open Graph & Twitter Cards)','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Shiriki wa blok ya Ikoni za Kijamii: URLs: zinashughulikiwa na Shirikisho la Kijamii la LF lililojengwa ndani (SEO → Kushiriki Kijamii)','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'vitendo vya nakala / asili / otomatiki: vinashughulikiwa na LF\'s social-share.js','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Wakati kinapatikana, mu- plugin inashughulikia seti ya OG ya msingi na LF hutoa lebo za lugha pekee (hali ya kiotomatiki). Kuiondoa kunabadilisha LF kuwa hali kamili ya OG moja kwa moja.','Debug Files'=>'Faili za Kagua','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Wakati kumbukumbu za kagua zinapokua zimewezeshwa (kupitia kitufe cha chini au kwa kufafanua LINGUAFORGE_AI_DEBUG katika wp-config.php), vipengele vya Tafsiri na template ya FSE huandika maombi yao ya AI na majibu kwenye diski kwa ajili ya utatuzi wa matatizo. Tumia sehemu hii kufuatilia matokeo hayo na kuyaondoa mara umepata unachohitaji — faili zinaweza kukua kwa haraka kwenye kurasa kubwa. Sanidi saraka ya malengo kupitia kichungi cha linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Faili za kagua zimesafishwa. Faili %d imeondolewa.' . "\0" . 'Faili za kagua zimesafishwa. Faili %d zimeondolewa.','Debug logging enabled.'=>'Kumbukumbu za kagua zimewezeshwa.','Debug logging disabled.'=>'Kumbukumbu za kagua zimezimwa.','Debug logging'=>'Kumbukumbu za kagua','Write AI prompts and responses to disk for troubleshooting'=>'Andika maombi ya AI na majibu kwenye diski kwa ajili ya utatuzi wa matatizo','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Imezuiwa kwa nguvu na mabadiliko ya LINGUAFORGE_AI_DEBUG katika wp-config.php. Ondoa mstari huo ili kudhibiti kitufe hiki kutoka hapa.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Imezimwa kwa nguvu na mabadiliko ya LINGUAFORGE_AI_DEBUG katika wp-config.php. Ondoa mstari huo ili kudhibiti kitufe hiki kutoka hapa.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Faili huwasili kwenye saraka iliyo chini. Inafaa kwa utatuzi wa matatizo ya tafsiri — zima mara unapata unachohitaji ili faili zisikusanyike. Pia unaweza kuizuia kutoka wp-config.php kwa kutumia `define( \'LINGUAFORGE_AI_DEBUG\', true );` ambayo inazidi kitufe hiki.','Currently:'=>'Sasa hivi:','✓ Enabled'=>'✓ Imewashwa','✗ Disabled'=>'✗ Imesimamishwa','Directory'=>'Saraka','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Chuja kwa kutumia linguaforge_debug_dir ili kuelekeza matokeo ya kagua mahali pasipo umma.','Files'=>'Faili','.txt file(s) in the directory'=>'.txt faili(za) kwenye saraka','Save Debug Setting'=>'Hifadhi Mipangilio ya Kagua','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Futa faili zote za .txt kwenye saraka ya kagua? Saraka yenyewe itabaki ili kuendelea kuandika mafaili ya kagua ya baadaye.','Clear Debug Files'=>'Futa Faili za Kagua','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge hutoa lebo za <link rel="alternate" hreflang> kwa kila lugha iliyowekwa kwenye kila ukurasa, ikijumuisha x-default inayorejelea lugha ya chanzo. Hii ni ishara kuu ya SEO ya lugha nyingi kwa Google na injini nyingine za utafutaji — hakuna kiambatanisho cha SEO cha ziada kinachohitajika.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Wakati Yoast SEO, Rank Math, All in One SEO, au SEOPress iko hai, LF huondoa kiotomatiki lebo zao za hreflang kwa kutumia kichungi. Plugins za SEO kwa ujumla hutoa hreflang kwa msingi wa muundo wa URL wa lugha moja na hawawezi kuzingatia usanidi wako wa mwelekeo wa lugha nyingi; matokeo ya LF daima ni sahihi.','Hreflang settings saved.'=>'Mipangilio ya Hreflang imehifadhiwa.','Hreflang output'=>'Matokeo ya Hreflang','Output hreflang tags in wp_head'=>'Toa lebo za hreflang kwenye wp_head','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Zima tu kwa tovuti zisizo na kichwa au utekelezaji wa hreflang wa kawaida. Wakati imezimwa, LF haitoi tena lebo ya canonical ya WordPress na haitasawazisha matokeo ya programu-jalizi za SEO za hreflang.','Current status'=>'Hali ya sasa','✓ Hreflang active'=>'✓ Hreflang imetumika','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'LF inatoa hreflang tags na inaibadilisha canonical ya WordPress core na canonical inayorejelea yenyewe kwa kila toleo la lugha.','LF is suppressing hreflang output from: %s'=>'LF inazima matokeo ya hreflang kutoka: %s','Save Hreflang Settings'=>'Hifadhi Mipangilio ya Hreflang','Language Overrides'=>'Mabadiliko ya Lugha','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Pakua faili zilizokusanywa za .mo kubadilisha maneno ya programu za watu wengine kwa maeneo maalum — kwa mfano, tafsiri maalum ya VikBooking inayotumia "apartment" badala ya "room". Faili lazima zifuate muundo wa jina la WordPress: {textdomain}-{locale}.mo (mfano, vikbooking-ca.mo). Zina hifadhiwa kwenye folda ya uploads na huishi baada ya sasisho la programu.','Override file uploaded successfully.'=>'Faili ya mabadiliko imepakuliwa kwa mafanikio.','Override file deleted.'=>'Faili ya mabadiliko imefutwa.','No file was selected.'=>'Hakuna faili iliyochaguliwa.','Only .mo files are accepted.'=>'Faili za .mo pekee zinakubaliwa.','The upload failed — please try again.'=>'Upakuaji umeshindwa — tafadhali jaribu tena.','Could not save the file. Check that the uploads folder is writable.'=>'Haiwezekani kuhifadhi faili. Hakikisha folda ya uploads ina haki ya kuandika.','Invalid filename.'=>'Jina la faili si sahihi.','Security check failed — file path is not permitted.'=>'Uhakiki wa usalama umeshindwa — njia ya faili haikubaliki.','An unknown error occurred.'=>'Hitilafu isiyojulikana imetokea.','Text domain / locale'=>'Uwanja wa lugha / muktadha','Size'=>'Ukubwa','Delete all files for this override (both .mo and .po)?'=>'Futa faili zote za mabadiliko haya (zote .mo na .po)?','Delete'=>'Futa','No override files uploaded yet.'=>'Hakuna faili za mabadiliko zilizopakiwa bado.','Upload .mo file'=>'Pakua faili ya .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Inakubali faili zilizokusanywa za .mo pekee. Jina la faili lazima zifuate muundo wa {textdomain}-{locale}.mo. Kupakia faili lenye jina sawa na la zamani kutalibadilisha.','Upload Override'=>'Pakua Mabadiliko','Loco Translate — Copy to Safe Storage'=>'Loco Tafsiri — Nakili kwa Hifadhi Salama','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate hifadhi tafsiri zake maalum katika wp-content/languages/loco/ — mahali ambapo inaweza kufutwa kwa kimya na sasisho la WP, kufanywa upya kwa programu, au ikiwa Loco Translate yenyewe inatoweka. Nakili faili hapa huziweka kwenye saraka ya Lingua Forge i18n-overrides, ambayo huendelea kuwa hai kupitia matukio yote hayo na hujumuishwa kiotomatiki kila wakati.','File copied to safe storage successfully.'=>'Faili imehamishwa kwa mafanikio kwenye hifadhi salama.','Source file not found.'=>'Faili ya chanzo haipatikani.','Could not copy the file. Check that the uploads folder is writable.'=>'Haiwezekani kunakili faili. Hakikisha folda ya uploads ina haki ya kuandika.','Invalid file reference.'=>'Rejea ya faili si sahihi.','Type'=>'Aina','✓ In safe storage'=>'✓ Katika hifadhi salama','Copy to safe storage'=>'Nakili kwenye hifadhi salama','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Hakuna faili maalum za Loco Translate bado. Zinaonekana hapa mara tu unapohifadhi tafsiri kwenye Loco Translate.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge hutoa meta tags za Open Graph na Twitter Card ili URLs zilizoshirikiwa zionyeshe lugha sahihi, kichwa, maelezo, na picha kwenye majukwaa ya kijamii.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Tofauti na hreflang — ambapo LF daima huongeza nguvu plugin nyingine kwa sababu hawawezi kujua usanidi wako wa lugha nyingi — Open Graph ni tofauti: Yoast, Rank Math, na plugins zinazofanana tayari hutoa lebo sahihi za OG kwa maudhui yako. Kuziiga hakutoa thamani yoyote. Katika hali ya kiotomatiki, LF huamua plugin za SEO zinazofanya kazi na huongeza tu kile ambacho hawawezi kutoa: og:locale (lugha ya sasa) na og:locale:alternate (lugha zote zilizowekwa).','Open Graph settings saved.'=>'Mipangilio ya Open Graph imehifadhiwa.','Open Graph output'=>'Utoaji wa Open Graph','Output Open Graph tags in wp_head'=>'Toa lebo za Open Graph kwenye wp_head','Output mode'=>'Njia ya kutoa','Auto (recommended)'=>'Automu (inapendekezwa)','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Gundua programu-jalizi za SEO zinazofanya kazi (Yoast, Rank Math, n.k.) wakati wa runtime. Toa tu og:locale + og:locale:alternate wakati programu-jalizi nyingine tayari inatoa seti kamili ya OG; toa seti kamili wakati hakuna inayoonekana.','Locale only'=>'Lugha pekee','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Daima toa tu og:locale na og:locale:alternate. Tumia wakati plugin au mandhari nyingine inashughulikia seti kamili ya OG.','Full'=>'Kamili','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Daima toa seti kamili ya OG + Twitter Card bila kujali plugins nyingine. Tumia tu ikiwa hakuna plugin nyingine inatoa lebo za OG.','Disabled'=>'Imelazimishwa','Do not output any OG tags.'=>'Usitoe lebo yoyote ya OG.','Default OG image'=>'Picha ya OG chaguo-msingi','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL ya picha ya mbadala inayotumika wakati ukurasa hauja na picha maarufu, nembo ya tovuti, au ikoni ya tovuti. Inaonyeshwa katika maoni ya kijamii kwa hifadhidata, faharasa ya blogu, na kurasa zozote za pekee bila picha ndogo.','— Disabled'=>'— Imelzimwa','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Imo — lebo za eneo pekee (og:locale, og:locale:alternate)','✓ Active — full OG + Twitter Cards'=>'✓ Imo — OG kamili + Kadi za Twitter','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Mu-plugin wa zamani wa lf-social-share umegunduliwa. LF inahifadhi seti ya OG ya msingi kwa mu-plugin na inatoa og:locale + og:locale:alternate tu. Unaweza kuzima mu-plugin — Social Share iliyojengwa ndani ya LF (SEO → Social Share tab) na Cover ya Open Graph zinafanya kazi sawa.','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Programu-jalizi(zi) za SEO zilizogunduliwa: %s. LF inatoa og:locale na og:locale:alternate pekee; programu-jalizi iliyogunduliwa inashughulikia seti kamili ya OG.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Hakuna plugin ya OG ya nje iliyogunduliwa. LF inatoa seti kamili ya OG + Twitter Card.','Save Open Graph Settings'=>'Hifadhi Mipangilio ya Open Graph','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge hutoa data iliyopangwa ya Schema.org JSON-LD ili injini za utafutaji kuelewa aina ya maudhui yako, lugha, na metadata. Hii ndiyo njia kuu ya kuwasiliana maelezo ya inLanguage kwa Google na wakusanyaji wengine.','Schema output deferred.'=>'Matokeo ya Schema yameahirishwa.','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s ni hai na tayari inatoa Schema.org JSON-LD. Lingua Forge imezima toleo lake la schema ili kuzuia michoro inayopingana. Tofauti na Open Graph — ambapo LF huongeza og:locale juu ya toleo la plugin nyingine — schema haiwezi kuongezwa kwa usafi: michoro ya JSON-LD inayojirudia au inayokinzana husababisha makosa ya uthibitishaji. Zima toleo la schema kwenye plugin iliyogunduliwa ikiwa unataka LF kushughulikia data iliyowekwa muundo.','Schema.org settings saved.'=>'Mipangilio ya Schema.org yamehifadhiwa.','Schema.org output'=>'Matokeo ya Schema.org','Output Schema.org JSON-LD in wp_head'=>'Muundo wa JSON-LD wa Schema.org wa pato katika wp_head','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Imefungwa — plugin ya SEO inayopingana iko hai. Tazama arifa hapo juu.','Article / WebPage'=>'Makala / Tovuti','Output Article or WebPage schema on singular posts and pages'=>'Toa schema ya Article au WebPage kwenye machapisho na kurasa za pekee','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Post za blog hutumia Article; aina nyingine za post na kurasa zote hutumia WebPage. Inajumuisha kichwa, maelezo, inLanguage, url, tarehe iliyochapishwa, tarehe iliyobadilishwa, picha, na mchapishaji.','WebSite'=>'Tovuti','Output WebSite schema on the front page and blog index'=>'Toa muundo wa WebSite kwenye ukurasa wa mbele na orodha ya blogu','Includes site name, url, and inLanguage.'=>'Inajumuisha jina la tovuti, url, na inLanguage.','Product'=>'Bidhaa','Output Product schema on WooCommerce product pages'=>'Toa schema ya Product kwenye kurasa za bidhaa za WooCommerce','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Inajumuisha jina, maelezo, inLanguage, url, picha, na Ofa yenye bei, sarafu ya bei, na upatikanaji. Bei na upatikanaji vinatoka kwa bidhaa ya lugha asili (mfano wa hisa zinazoshirikishwa).','Currently emitting'=>'Kwa sasa inatoa','Article / WebPage — all singular posts and pages'=>'Makala / Tovuti — post na kurasa zote za pekee','WebSite — front page / blog index'=>'Tovuti — ukurasa wa mbele / orodha ya blogu','Product — WooCommerce product pages'=>'Bidhaa — kurasa za bidhaa za WooCommerce','Nothing — all types disabled'=>'Hakuna kitu — aina zote zimezimwa','Save Schema.org Settings'=>'Hifadhi Mipangilio ya Schema.org','Blog / Editorial'=>'Blogu / Mhariri','Product / eCommerce'=>'Bidhaa / eCommerce','Landing / Short-form'=>'Kuruka / Fomu fupi','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Chuja kwa lugha na aina ya chapisho, tembelea maudhui yako, na bofya Tathmini kwa kipengele chochote ili kuendesha ukaguzi wa SEO wa kanuni — urefu wa kichwa, maelezo ya meta, idadi ya maneno, muundo wa vichwa, ufunuo wa picha ya alt, na viungo vya ndani.','Treat H2 as H1 equivalent'=>'Tafsiri H2 kama H1 sawa','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Washa wakati mada yako inatoa kichwa cha chapisho kama H2 badala ya H1 (ya kawaida katika baadhi ya mandhari za blok). Mchambuzi huinua ukurasa uliotolewa na, ikiwa haioni H1 bali hupata H2, huinua H2 ya kwanza kuwa H1 kwa ajili ya alama za alama.','Save analysis settings'=>'Hifadhi mipangilio ya uchambuzi','Per-Post Analysis'=>'Uchambuzi wa Kila Chapisho','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Chagua chapisho na fanya ukaguzi wa kina wa SEO ili kuona matokeo kwa kila kipimo na alama kwa kipengele hicho.','Language'=>'Lugha','source'=>'chanzo','All types'=>'Aina zote','Load content'=>'Pakia maudhui','Batch Analysis'=>'Uchambuzi wa Kundi','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Fanya ukaguzi kamili wa SEO kwa chapisho zote zilizochapishwa kwa lugha moja au zaidi zinazofanya kazi. Alama zimehifadhiwa kwa kila chapisho na zinaonyeshwa kwenye alama za safu ya Lugha kwenye orodha ya machapisho.','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'Kurasa za mfumo wa WooCommerce (Duka, Mzigo, Malipo, Akaunti Yangu) hazijumuishwa — yaliyomo yao yanashughulikiwa na WooCommerce na hayawezi kuboreshwa kupitia mabadiliko ya SEO.','Post type'=>'Aina ya chapisho','Default profile'=>'Profaili chaguo-msingi','— Auto-detect —'=>'— Tambua kiotomatiki —','Analyse all languages'=>'Chambua lugha zote','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Uchambuzi wa kundi: bidhaa za WooCommerce → Profaili ya Bidhaa; ukurasa wa mbele wa static → Profaili ya Kutua; kila kitu kingine → Profaili ya Blogu. Chagua profaili maalum ili kuibadilisha hii kwa machapisho yote.','%d post'=>'%d chapisho' . "\0" . '%d machapisho','Last run: %s ago'=>'Endesha mara ya mwisho: %s zilizopita','Never run'=>'Usiwe kukimbia kamwe','avg'=>'avg','(partial)'=>'(sehemu)','Analyse'=>'Chambua','(no title) #%d'=>'(hakuna kichwa) #%d','Invalid post ID.'=>'ID batili ya chapisho.','Post not found or not published.'=>'Chapisho hakipatikani au hakijachapishwa.','~%d min read'=>'~%d dakika kusoma' . "\0" . '~%d dakika kusoma','No title set.'=>'Hakuna kichwa kilichowekwa.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Kichwa ni %1$d herufi — inaweza kukatwa katika SERPs (jaribu kuwa chini ya %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'Kichwa ni herufi %d tu — jaribu angalau herufi 10.','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Kichwa cha neno kimoja (%d herufi) — kuongeza neno la pili huongeza uwazi na ufunuo wa maneno muhimu.','%1$d chars, %2$d words — good title.'=>'%1$d herufi, %2$d maneno — kichwa kizuri.','Using LF AI meta description.'=>'Kutumia meta maelezo ya AI ya LF.','No LF meta description set — using excerpt/content.'=>'Hakuna maelezo ya meta ya LF yaliowekwa — inatumia excerpt/maudhui.','No meta description found. Generate one via the AI meta description feature.'=>'Hakuna maelezo ya meta yaliyopatikana. Tengeneza moja kwa kutumia kipengele cha AI cha maelezo ya meta.','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d herufi — fupi sana (lengo ni %2$d–%3$d). %4$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d herufi — huenda ikakatwa kwenye matokeo ya utafutaji (baki chini ya %2$d). %3$s','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d herufi — nzuri, juu kidogo ya kiwango bora cha %2$d lakini ndani ya kiwango kinachokubalika cha herufi %3$d. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d herufi — urefu bora. %2$s','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d maneno — maudhui machache sana. Fikiria kupanua hadi angalau %2$d maneno.','%1$d words — below recommended minimum of %2$d.'=>'%1$d maneno — chini ya kiwango cha chini kinachorekomendwa cha %2$d.','%d words.'=>'%d maneno.','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'Mode ya H2-kama-H1 imewezeshwa — kichwa kinahesabiwa kama sawa na H1. (Vichwa vinaweza kutotambuliwa kutoka kwa ukurasa uliotolewa; hakikisha mandhari yako inatoa kichwa kwa usahihi.)','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Hakuna H1 iliyopatikana. Kawaida kichwa cha chapisho ni H1 — hakikisha mandhari yako inachapisha hicho.','%d H1 tags found — a page should have exactly one H1.'=>'%d lebo za H1 zimepatikana — ukurasa unapaswa kuwa na H1 moja tu.','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'H1 1 ✓ — hakuna H2, lakini kichwa kidogo cha H3 kimepatikana (%d). Muundo ni wa kuridhisha.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'H1 1 ✓ — maudhui mafupi (%d aya), kichwa kidogo hakihitajiki.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'H1 1 ✓ — hakuna vichwa vidogo vya H2 (inayokubalika kwa aina hii ya maudhui).','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — hakuna H2 au H3 subheadings zilizopatikana. Kuongeza H2s kunaboresha muundo.','1 H1 ✓, %1$d H2, %2$d H3.'=>'H1 moja ✓, %1$d H2, %2$d H3.','No images found in content.'=>'Hakuna picha zilizopatikana kwenye maudhui.','%1$d of %2$d image(s) missing alt text.'=>'%1$d ya %2$d picha hazina maandishi ya alt.','%d image(s), all have alt text.'=>'%d picha, zote zina maandishi ya alt.','No links found. Internal links improve crawlability and user navigation.'=>'Hakuna viungo vilivyopatikana. Viungo vya ndani vinaboresha utafutaji na urambazaji wa mtumiaji.','No links found.'=>'Hakuna viungo vilivyopatikana.','%d external link(s), no internal links. Add internal links to related content.'=>'%d kiungo nje, hakuna viungo vya ndani. Ongeza viungo vya ndani kwa maudhui yanayohusiana.','%d external link(s), no internal links.'=>'Kiungo cha nje cha %d, hakina viungo vya ndani.','%1$d internal, %2$d external.'=>'%1$d ndani, %2$d nje.','Post not found.'=>'Chapisho hakipatikani.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Hakuna mtoa huduma wa AI aliyepangwa. Ongeza ufunguo wa API katika Mipangilio → Funguo za API.','No response from AI provider. Check your API key and try again.'=>'Hakuna majibu kutoka kwa mtoa huduma wa AI. Angalia ufunguo wako wa API na jaribu tena.','AI returned an unexpected response format. Please try again.'=>'AI imerudisha muundo wa majibu usiotarajiwa. Tafadhali jaribu tena.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge hutoa ramani ya tovuti ya XML iliyojitenga kwenye /lf-sitemap.xml ambayo huongeza viungo vya lugha mbadala kwa maudhui yako yote yaliyotafsiriwa. Ramani hii ya tovuti inaambatana na ramani ya tovuti ya WordPress na ramani ya tovuti ya plugin yoyote ya SEO — haitabadilishi.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Ramani ya tovuti ya msingi ya WordPress inaorodhesha URL zote za maudhui yako. Ramani ya tovuti ya LF inawaambia injini za utafutaji jinsi toleo za lugha zinavyohusiana kwa njia ya xhtml:link hreflang mbadala. Wasilisha zote kwa Google Search Console kwa ufanisi kamili.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s ni hai na inazalisha ramani yake ya tovuti. Ramani hiyo ni tofauti na ya LF. Zote zinapaswa kuwasilishwa kwa Google Search Console: ramani ya SEO inaorodhesha maudhui yako; ramani ya LF huongeza viungo mbadala vya lugha nyingi. Ramani ya LF inatangazwa moja kwa moja kwenye robots.txt.','Sitemap settings saved.'=>'Mipangilio ya Ramani ya Tovuti yamehifadhiwa.','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Hifadhi ya Ramani ya Tovuti imefutwa. Itatengenezwa tena wakati wa ziara inayofuata kwenye URL ya ramani ya tovuti.','Sitemap output'=>'Matokeo ya Ramani ya Tovuti','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Unda ramani ya lugha nyingi kwenye /lf-sitemap.xml','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Wakati imewezeshwa, URL ya ramani ya tovuti inatangazwa moja kwa moja katika robots.txt na hufanyiwa upya wakati maudhui yaliyotafsiriwa yanahifadhiwa.','Sitemap URL'=>'URL ya Ramani ya Tovuti','Submit this URL to Google Search Console alongside your main sitemap.'=>'Wasilisha URL hii kwa Google Search Console pamoja na ramani yako kuu ya tovuti.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Bado haijatengenezwa. Ramani ya tovuti hujengwa kwenye ziara ya kwanza kwenye URL ya ramani ya tovuti na huhifadhiwa kwa masaa 24.','✓ Active — %d URL entry with language alternates'=>'✓ Imo — ingizo la URL %d lenye mabadiliko ya lugha' . "\0" . '✓ Imo — ingizo la URL %d lenye mabadiliko ya lugha','No translated content found. The sitemap will populate once posts have been translated.'=>'Hakuna maudhui yaliyotafsiriwa yaliyopatikana. Ramani ya tovuti itajaa mara baada ya machapisho kutafsiriwa.','Last generated: %s'=>'Imezalishwa mwisho: %s','Save Sitemap Settings'=>'Hifadhi Mipangilio ya Ramani ya Tovuti','Flush Sitemap Cache'=>'Fagia Hifadhi ya Ramani','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Inalazimisha upya ramani ya tovuti wakati wa ombi lijalo. Tumia baada ya kuingiza kwa wingi au kuhariri kwa mikono uhusiano wa tafsiri.','IndexNow'=>'IndexNow','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'IndexNow ni itifaki wazi inayoungwa mkono na Bing, Yandex, na injini nyingine za utafutaji. Wakati chapisho kilichotafsiriwa kinachapishwa au kusasishwa, Lingua Forge huarifu kiotomatiki injini zote zinazoshiriki kwa mpigo mmoja — hakuna upigaji kura, hakuna kusubiri kwa kuvinjari robots.txt inayofuata.','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'IndexNow inachukua nafasi ya mwisho wa zamani wa Bing na Yandex wa sitemap-ping. Google hujua ramani za tovuti kupitia amri ya robots.txt Sitemap: kama zamani.','✓ All URLs submitted to IndexNow successfully.'=>'✓ URLs zote zilizowasilishwa kwa IndexNow zimefanikiwa.','No translated URLs found to submit. Publish some translated posts first.'=>'Hakuna URLs zilizotafsiriwa zilizopatikana kuwasilisha. Chapisha baadhi ya machapisho yaliyotafsiriwa kwanza.','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ Uwasilishaji wa IndexNow umeshindwa. Hakikisha faili la funguo linapatikana kwa umma (angalia chini) na jaribu tena.','Verification key'=>'Funguo la uthibitishaji','Key file served automatically at: %s'=>'Faili la funguo linatolewa kiotomatiki kwa: %s','Key could not be generated. Check that the site has write access to WordPress options.'=>'Funguo hauwezi kuzalishwa. Hakikisha tovuti ina ruhusa ya kuandika kwenye chaguzi za WordPress.','Key file status'=>'Hali ya faili la funguo','✓ Key file is publicly reachable.'=>'✓ Faili la funguo linapatikana kwa umma.','✗ Key file is not reachable.'=>'✗ Faili la funguo halipatikani.','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'Vifaa vya IndexNow vinathibitisha faili ya funguo kabla ya kukubali mawasilisho. Ikiwa faili haitafikiwa, mawasilisho yatakataliwa kwa kosa la 403.','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'Sababu za kawaida: kuhifadhi kwa kurasa kamili (futa), kiambatishi cha usalama kinachozuia faili za .txt, au kanuni maalum ya Nginx/Apache. Faili hiyo hutumika na LF kwa kila ombi — hakuna faili halisi inayohifadhiwa kwenye diski.','Submit all URLs'=>'Wasilisha URLs zote','Submit all URLs via IndexNow'=>'Wasilisha URLs zote kupitia IndexNow','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'Inasafirisha kila URL iliyochapishwa, inayosimamiwa na LF kwa IndexNow kwa kundi moja. Uwasilishaji wa kiotomatiki tayari unafanya kazi kila wakati wa kuchapisha/kasasisha — tumia hii tu baada ya uingizaji wa kundi au wakati wa kuanzisha IndexNow kwa mara ya kwanza.','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'Google haishariki katika IndexNow. Inakagundua sitemaps kupitia robots.txt Sitemap: directive — ambayo LF tayari imesanidi. Tumia Google Search Console kuangalia kufunika kwa indexing.','Open Search Console →'=>'Fungua Google Search Console →','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt imesasishwa na maagizo ya Ramani ya Tovuti.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Robots.txt ya kimwili imepatikana. Amri ya Ramani ya LF iko.','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Kuna faili halali ya robots.txt kwenye mzizi wa tovuti. WordPress\'s virtual robots.txt — na LF\'s Sitemap: filter — zinapita. Ramani ya LF haijatangazwa kwa injini za utafutaji.','Add Sitemap directive to robots.txt'=>'Ongeza amri ya Ramani ya Tovuti kwenye robots.txt','Appends the following line to your existing robots.txt: %s'=>'Inasababisha mstari ufuatao kwenye robots.txt yako iliyopo: %s','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS imewekwa.','Add the following line to your robots.txt manually:'=>'Ongeza mstari ufuatao kwenye robots.txt kwa mikono:','View current robots.txt'=>'Tazama robots.txt ya sasa','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Hakuna faili halali ya robots.txt iliyopatikana. WordPress inazalisha kwa njia ya mtandao na amri ya Sitemap ya LF imejumuishwa kiatomati.','The following directive is active in your virtual robots.txt:'=>'Agizo lifuatalo ni hai katika robots.txt yako ya mtandao:','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Mabadiliko ya faili yamezimwa (DISALLOW_FILE_MODS).','Could not write to robots.txt. Check file permissions.'=>'Haiwezi kuandika kwa robots.txt. Angalia ruhusa za faili.','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge huongeza bloki la Ikoni za Kijamii za WordPress Core na URLs za kushiriki za mabadiliko. Weka kiungo cha ikoni yoyote kwa thamani ya "share:" na LF huandika upya kuwa URL sahihi ya kushiriki au kitendo cha JavaScript wakati wa kuonyesha — hakuna msimbo maalum au plugin ya watu wa tatu inayohitajika.','Social Share settings saved.'=>'Mipangilio ya Shiriki la Kijamii yamehifadhiwa.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Mu- plugin wa lf-social-share ni hai. Social Share iliyojengwa ndani ya Lingua Forge haifanyi kazi — mu-plugin inashughulikia uandishi upya wa URL za kushiriki na vitendo vya JS.','Social Share'=>'Shiriki Kijamii','Enable Social Share URL rewriting for Social Icons blocks'=>'Wezesha upya URL za Shirika la Kijamii kwa vikundi vya Ikoni za Kijamii','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Imelazimishwa kwa sababu mu-plugin ya lf-social-share tayari inatoa huduma hii.','Save Social Share Settings'=>'Hifadhi Mipangilio ya Shiriki Kijamii','How to use'=>'Jinsi ya kutumia','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Katika mhariri wa kikundi, ongeza kikundi cha Ikoni za Kijamii. Kwa kila ikoni, fungua mipangilio ya kiungo na ingiza moja ya thamani za "share:" chini kama URL. Kwenye mbele, LF inabadilisha na URL sahihi ya kushiriki kwa ukurasa wa sasa.','External share services'=>'Huduma za ushirikiano za nje','URL to enter'=>'URL ya kuingiza','Action'=>'Kitendo','Share on Facebook'=>'Shiriki kwenye Facebook','Post on X / Twitter'=>'Chapisho kwenye X / Twitter','Share on LinkedIn'=>'Shiriki kwenye LinkedIn','Send via WhatsApp'=>'Tuma kupitia WhatsApp','Send via Telegram'=>'Tuma kupitia Telegram','Submit to Reddit'=>'Wasilisha kwa Reddit','Pin on Pinterest'=>'Bonyeza kwenye Pinterest','Share on Mastodon'=>'Shiriki kwenye Mastodon','Share via email (mailto:)'=>'Shiriki kupitia barua pepe (mailto:)','JavaScript-powered actions'=>'Vitendo vinavyotegemea JavaScript','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Nakili URL ya sasa kwenye ubao wa kunakili. Inaonyesha toast ya "Kiungo kimenakiliwa" kwa mafanikio.','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Fungua karatasi ya kushiriki ya wavuti ya asili ya simu (iOS, Android, baadhi ya kompyuta). Inarudiwa kwa nakala kwenye ubao wa kunakili ikiwa haipo.','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Tumia kushiriki asili inapopatikana; rudisha nakala kwenye ubao wa kunakili. Pendekezo la chaguo-msingi kwa vitufe vya "Shiriki".','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'URL ya kushiriki daima inaonyesha ukurasa wa sasa — hakuna haja ya kuingiza URL kwa mkono. kichungi cha linguaforge_social_share_url hukuruhusu kubadilisha URL iliyotatuliwa kwa huduma yoyote.','Configuration issue: WP site language has no content on this site'=>'Tatizo la usanidi: Lugha ya tovuti ya WP haina maudhui kwenye tovuti hii','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'Lugha ya tovuti ya WordPress (%1$s) inakartisha kwa nambari ya lugha "%2$s", lakini hakuna chapisho lolote kwenye tovuti hii lililoandikwa kwa alama _lf_lang=%2$s. Hii husababisha maswali ya bidhaa ya WooCommerce kurudi matokeo ya sifuri, picha za bidhaa kushindwa, na maswali yote ya maudhui yaliyochujwa kwa lugha kuvunjika.','Fix: go to'=>'Rekebisha: nenda kwa','Settings → General → Site Language'=>'Mipangilio → Jumla → Lugha ya Tovuti','and set it to one of your actual content languages (e.g. %s).'=>'na uiweke kwa moja ya lugha zako halisi za maudhui (kwa mfano %s).','Environment'=>'Mazingira','Lingua Forge version'=>'Toleo la Lingua Forge','WordPress version'=>'Toleo la WordPress','PHP version'=>'Toleo la PHP','Active theme'=>'Mandhari inayofanya kazi','(FSE / block theme)'=>'(FSE / mandhari ya kizuizi)','(classic theme)'=>'(mandhari ya jadi)','URL structure'=>'Muundo wa URL','Subdomain (de.example.com)'=>'Subdomain (de.example.com)','Path prefix (/de/)'=>'Kiambatanisho cha njia (/de/)','WP instance language'=>'Lugha ya mfano wa WP','not a content language — see notice above'=>'si lugha ya maudhui — tazama taarifa hapo juu','Primary content language'=>'Lugha kuu ya maudhui','Active languages'=>'Lugha zinazofanya kazi','PHP max_execution_time'=>'Muda wa utekelezaji wa juu wa PHP','No PHP limit'=>'Hakuna kikomo cha PHP','(server/FPM timeout still applies)'=>'(muda wa server/FPM bado unatumika)','AI translation and batch analysis may time out. Recommend 120s or more.'=>'Tafsiri ya AI na uchambuzi wa kundi linaweza kuchukua muda mrefu. Pendekeza sekunde 120 au zaidi.','PHP memory_limit'=>'Kiwango cha kumbukumbu cha PHP','AI Configuration'=>'Mipangilio ya AI','(active)'=>'(kinachofanyika)','Configured'=>'Imesanidiwa','No key'=>'Hakuna ufunguo','— AI features are disabled.'=>'— Vipengele vya AI vimezimwa.','Add key →'=>'Ongeza ufunguo →','Light model'=>'Mfano mwepesi','Quality model'=>'Mfano wa Ubora','Active preset'=>'Mipangilio inayofanya kazi','Daily quota'=>'Kiasi cha kila siku','Unlimited'=>'Bila kikomo','requests / day'=>'maombi / siku','Permalink Structure'=>'Muundo wa Permalink','Permalink structure is compatible with Lingua Forge path routing.'=>'Muundo wa permalink unalingana na uendeshaji wa njia wa Lingua Forge.','Plain permalinks are not supported.'=>'Permalinks rahisi hazisaidwi.','Path routing requires a post-name based permalink structure. Change it in'=>'Uendeshaji wa njia unahitaji muundo wa permalink wa jina la chapisho. Badilisha katika','Settings → Permalinks'=>'Mipangilio → Permalinks','Numeric permalink structure is not supported.'=>'Muundo wa permalink wa nambari hauungi mkono.','Switch to a post-name based structure in'=>'Badilisha kwa muundo wa jina la chapisho katika','SEO Plugins'=>'Programu-jalizi za SEO','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Hakuna programu-jalizi za SEO za watu wa tatu zilizogunduliwa. Lingua Forge inashughulikia matokeo yote ya SEO ya lugha nyingi.','Active: %s.'=>'Inafanya kazi: %s.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Tazama Mipangilio → SEO → Ulinganifu kwa jedwali kamili la tabia za kila kipengele.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce haijashikiliwa.','Shop'=>'Duka','Cart'=>'Karatasi','Checkout'=>'Malipo','My Account'=>'Akaunti Yangu','WooCommerce version'=>'Toleo la WooCommerce','Order storage'=>'Hifadhi ya Oda','High-Performance Order Storage (HPOS)'=>'Hifadhi ya Oda ya Utendaji wa Juu (HPOS)','Custom tables — LF post-meta filters do not affect orders.'=>'Meza maalum — vichujio vya LF post-meta havina athari kwa maagizo.','Shared / compatibility mode'=>'Mode ya Pamoja / ya Ulinganifu','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT zimesawazishwa — ya muda; vichujio vya LF post-meta vinatumika kwa nakala ya CPT.','Legacy post-based (CPT)'=>'Mzee wa chapisho (CPT)','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Amri katika wp_posts — hakikisha amri za duka la mpangilio zinachujwa kutoka kwa usafirishaji wa LF.','WcPageBridge active'=>'WcPageBridge imewashwa','Yes'=>'Ndiyo','No — WooCommerce integration class not loaded'=>'Hakuna — darasa la ujumuishaji wa WooCommerce halijapakuliwa','WooCommerce page translations'=>'Tafsiri za kurasa za WooCommerce','No secondary languages configured.'=>'Hakuna lugha za nyongeza zilizowekwa.','Active Plugins'=>'Vifungo Vinavyofanya kazi','No active plugins detected.'=>'Hakuna vifungo vinavyofanya kazi vilivyogunduliwa.','Version'=>'Toleo','_lf_lang Coverage'=>'Ufunuo wa _lf_lang','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'Chapisho bila _lf_lang haionekani kwa kila kichujio cha lugha cha Lingua Forge. Hii inaweza kutokea wakati maudhui yanapakiwa au kuundwa kabla ya programu-jalizi kuanzishwa.','All published posts have a _lf_lang value. No gaps detected.'=>'Machapisho yote yaliyochapishwa yana thamani ya _lf_lang. Hakuna mapengo yaliyogunduliwa.','Missing'=>'Inakosekana','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Zuia aina hii ya chapisho kutoka kwa usafirishaji wa lugha — machapisho yake hayatakuwepo hapa au kupokea _lf_lang. Hii haiwezi kurejeshwa kiotomatiki.','Exclude from routing'=>'Jumuisha kutoka kwa usafirishaji','excluded from routing'=>'imezuiwa kutoka kwa usafirishaji','Destructive action — read before proceeding'=>'Hatua ya kuharibu — soma kabla ya kuendelea','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Rekebisha lebo za kila chapisho linaloweza kusafirishwa lililoorodheshwa hapo juu kwa _lf_lang = %s. Chapisho katika aina za machapisho zilizozuiwa na usafirishaji hazigusiwi. Endesha hii tu baada ya kuingiza maudhui au kwenye uanzishaji wa awali — usitumie kama zana ya kurekebisha lugha kwa wingi.','Repair — assign _lf_lang = %s to all routable posts above'=>'Rekebisha — panga _lf_lang = %s kwa chapisho zote zinazoweza kusafirishwa hapo juu','Rewrite Rules'=>'Sheria za Kuandika Upya','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'Ving\'ang\'anizi vinavyomilikiwa na LF vinavyosajiliwa kwa sasa katika $wp_rewrite->extra_rules_top. Inafaa kwa kugundua 404s au migogoro ya mwelekeo. Nakili hizi wakati wa kuwasilisha ripoti ya hitilafu.','%d rule registered'=>'%d kanuni zilizosajiliwa' . "\0" . '%d kanuni zilizosajiliwa','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Hakuna sheria za kuandika upya LF zilizopatikana. Futa permalinks ikiwa hii siyo ya kawaida.','Debug Info'=>'Taarifa za Debug','Copy and paste into a GitHub issue or support request.'=>'Nakili na ubandike kwenye tatizo la GitHub au ombi la msaada.','Copy system info'=>'Nakili taarifa za mfumo','Copied!'=>'Imenakiliwa!','Repairing…'=>'Inafanyika…','Repair failed.'=>'Matengenezo yameshindwa.','Network error.'=>'Hitilafu ya mtandao.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Zuia aina hii ya chapisho kutoka kwa usafirishaji wa lugha? Machapisho yake hayatakuwepo kwenye orodha hii au kupokea _lf_lang. Unaweza kurejesha hii katika Mipangilio → Router → Mipangilio ya Uchujaji wa Maswali.','Excluding…'=>'Inazuiwa…','Failed to save exclusion.'=>'Imeshindwa kuhifadhi zuio.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d chapisho kilichotahiniwa na _lf_lang = %2$s.' . "\0" . '%1$d machapisho yaliyotahiniwa na _lf_lang = %2$s.','Uninstall Behaviour'=>'Futa Tabia ya Kifuta','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Hakikisha kinachotokea wakati msimamizi anafuta programu kutoka kwa Plugins → Plugins zilizowekwa → Futa. Mipangilio ya programu na cache za AI daima zinasafishwa. Uteuzi wa lugha na uhusiano wa tafsiri huzingatiwa kwa chaguo-msingi ili kusudi la kufuta au kufunga upya liweze kuendelea mahali pa kuacha.','Uninstall setting saved.'=>'Mipangilio ya kufuta imesimamiwa.','Delete content data on uninstall'=>'Futa data ya maudhui wakati wa kufuta','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Pia futa uteuzi wa lugha, uhusiano wa tafsiri, maelezo ya meta, kamusi, na Kumbukumbu ya Tafsiri wakati programu inafutwa.','Warning:'=>'Onyo:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Ikiwa imeshakaguliwa, kufuta programu kutafuta kwa muda mrefu utafuta uteuzi wa lugha, uhusiano wa tafsiri, maelezo ya meta, mipangilio ya ukurasa, kamusi ya AI, na Kumbukumbu ya Tafsiri kwa kila chapisho kwenye tovuti hii. Hii haiwezi kurejeshwa. Acha ishiwi isipokuwa unatoa msaada wa lugha nyingi kutoka kwa tovuti.','Save Uninstall Setting'=>'Hifadhi Mipangilio ya Kufuta','Today'=>'Leo','Last 7 days'=>'Siku 7 zilizopita','Last 30 days'=>'Siku 30 zilizopita','All time'=>'Wakati wote','AI Usage'=>'Matumizi ya AI','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Matumizi ya token yamekusanywa kwa kipengele, mtoa huduma, na mfano. Yamehifadhiwa kwenye kila simu ya mafanikio ya AI; ping za Jaribio la Muunganisho hazijumuishwa ili zisibakize jumla.','Check your account, billing, or remaining credits directly on the provider console:'=>'Angalia akaunti yako, bili, au salio lililobaki moja kwa moja kwenye jopo la mtoa huduma:','Anthropic Console'=>'Konsoli ya Anthropic','OpenAI Platform'=>'Jukwaa la OpenAI','Google AI Studio'=>'Studio ya AI ya Google','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Hakuna matumizi ya AI yaliyorekodiwa bado. Mara editor anapofanya tafsiri, kuunda maelezo ya meta, au kutumia kipengele kingine cha AI, jumla zitajitokeza hapa.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Hakuna matumizi ya AI yaliyorekodiwa katika dirisha lililochaguliwa (%s). Chagua wingi zaidi juu.','Provider'=>'Mtoa huduma','Model'=>'Mfano','Requests'=>'Maombi','Input tokens'=>'Token za ingizo','Output tokens'=>'Token za matokeo','Total tokens'=>'Jumla ya token','Total'=>'Jumla','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge huongeza mali za Open Graph maalum za WooCommerce kwenye kurasa za bidhaa ili kushiriki URL ya bidhaa kwenye Facebook, Pinterest, na majukwaa mengine kuonyesha aina sahihi ya bidhaa, bei, na upatikanaji.','WooCommerce SEO settings saved.'=>'Mipangilio ya SEO ya WooCommerce yamehifadhiwa.','Product Open Graph'=>'Open Graph ya Bidhaa','Add WooCommerce product tags to Open Graph output'=>'Ongeza lebo za bidhaa za WooCommerce kwenye matokeo ya Open Graph','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Wakati imewezeshwa, LF hutoa lebo za ziada za meta kwenye kurasa za bidhaa: og:type=product, og:price:amount, og:price:currency, og:availability, na sawa zao za jina la bidhaa zinazotumiwa na Facebook Catalog.','Tags emitted'=>'Lebo zilizotolewa','Tag'=>' Lebo','Value source'=>'Chanzo cha thamani','"product" (replaces "article")'=>'"bidhaa" (inachukua nafasi ya "makala")','WooCommerce product price'=>'Bei ya bidhaa ya WooCommerce','WooCommerce store currency'=>'Sarafu ya duka la WooCommerce','instock / oos / pending from WC stock status'=>'inashikilia / oos / inasubiri kutoka kwa hali ya hisa ya WC','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Bei na upatikanaji daima huonyesha bidhaa ya lugha asili (mfano wa hisa zinazoshirikishwa). Vitambulisho huonyeshwa tu wakati moduli ya Open Graph ya LF imewekwa kwa "Full" au "Auto" bila programu-jalizi ya SEO inayopingwa.','Save WooCommerce SEO Settings'=>'Hifadhi Mipangilio ya SEO ya WooCommerce','AI Provider'=>'Mtoa Huduma wa AI','AI Usage & Cache'=>'Matumizi ya AI na Cache','API Keys'=>'Vifunguo vya API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Vifunguo vinahifadhiwa kwa usalama kwa AES-256-CBC kabla havijasomwa kwenye hifadhidata ya WordPress. Siri ya usimbuaji inatokana na chumvi za uthibitishaji wa WordPress (wp-config.php), kwa hivyo funguo za maandishi hayagusi hifadhidata kamwe.','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'Anuani za API zinashughulikiwa na WordPress katika %s. Hakuna ufunguo unaohifadhiwa na Lingua Forge.','Settings → Connectors'=>'Mipangilio → Viunganishi','API Key'=>'Funguo la API','Paste your API key…'=>'Bandika funguo lako la API…','✓ Configured'=>'Imesasishwa','✗ Not configured'=>'Hijasasishwa','Test connection'=>'Jaribu muunganisho','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Acha tupu ili kuhifadhi funguo iliyopo. Ingiza thamani mpya kuibadilisha.','Remove stored key'=>'Ondoa funguo iliyohifadhiwa','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Funguo hili kwa sasa linatolewa na seva %s na haliwezi kuondolewa hapa. Ingiza funguo mpya juu ili kuilinda na thamani ya hifadhidata.','environment variable'=>'mabadiliko ya mazingira','PHP constant'=>'kifungo cha PHP','Alternative (server-side):'=>'Mbali (upande wa seva):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Pia unaweza kufafanua funguo kama mabadiliko ya mazingira au mabadiliko ya PHP (mfano katika wp-config.php). Vyanzo hivyo vinatumika kiotomatiki kama mbadala wakati hakuna funguo ya hifadhidata iliyohifadhiwa.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Ili kutumia siri ya usimbuaji wa desturi (badala ya thamani ya wp_salt iliyotolewa), ongeza hii katika wp-config.php:','Unknown provider.'=>'Mtoa huduma haijulikani.','No API key configured for this provider.'=>'Hakuna funguo ya API iliyowekwa kwa mtoa huduma huu.','Could not instantiate the provider.'=>'Haiwezi kuanzisha mtoa huduma.','Provider returned no response. Check the WordPress error log for details.'=>'Mtoa huduma hakurejesha majibu. Angalia kumbukumbu za makosa za WordPress kwa maelezo.','Enter a model identifier to test.'=>'Ingiza kitambulisho cha muundo kuojaribu.','No published post or page found to test with — publish some content first, or try Quick Translate directly.'=>'Hakuna chapisho au ukurasa uliochapishwa uliopatikana kuojaribu nao — chapisha maudhui fulani kwanza, au jaribu Quick Translate moja kwa moja.','(untitled)'=>'(bila kichwa)','Prompt template not found.'=>'Kiolezo cha maswali hakikupatikana.','Translation failed. Please try again.'=>'Tafsiri ilishindwa. Tafadhali jaribu tena.','The sample post has no visible text content to translate.'=>'Chapisho la sampuli halina maudhui ya maandishi yanayoonekana kutatamka.','Chunk prompt template not found.'=>'Kiolezo cha maswali ya kipande hakikupatikana.','Model returned no response. Check the WordPress error log for details.'=>'Muundo haukurudisha majibu. Angalia kumbukumbu ya hitilafu ya WordPress kwa maelezo.','Behavior'=>'Tabia','Block Editor'=>'Mhariri wa Block','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge inazuia vipengele viwili vya Gutenberg kwa chaguo-msingi ili kuweka tabia ya uhariri kuwa thabiti kati ya lugha. Chagua hapa ikiwa unahitaji uwezo kamili wa Gutenberg / FSE.','Block locking'=>'Kufunga kwa block','Allow editors to lock individual blocks'=>'Ruhusu wahariri kufunga blocks binafsi','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Inarudisha tena Gutenberg\'s canLockBlocks. Inafaa kwa templates za uhariri zinazohitaji kuzuia wachangiaji kuhamisha au kufuta blocks fulani.','Template mode'=>'Hali ya template','Allow Gutenberg template-editing mode on post screens'=>'Ruhusu hali ya uhariri wa template wa Gutenberg kwenye skrini za chapisho','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Inarudisha tena supportsTemplateMode. Muhimili kwa mchakato wa Uhariri wa Tovuti Kamili ambapo ubadilishaji wa template wa kiwango cha chapisho ni nia.','Compliance Preset'=>'Preset ya Uzingatiaji','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Hali kali ya uhifadhi kwa maudhui ya kisheria, kanuni, matibabu, au ya kiufundi. Wakati iko, kila kipengele cha AI kinatumia joto la sampuli ya chini na huongeza kifungu cha chini kwa amri ya mfumo — istilahi, nambari za makala, vitengo, majina ya chapa, na lugha za kanuni huhifadhiwa verbatim badala ya kufupishwa.','Global AI preset'=>'Preset ya AI Ulimwenguni','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, kwa kila kipengele','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Huweka tabia chaguo-msingi ya AI kwa vipengele vyote vya tovuti. Chapisho binafsi kinaweza kubadilisha hii kwa Tafsiri na Uundaji wa Maudhui kupitia sanduku la meta la Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Kawaida hutumia joto la kila kipengele kilichopimwa: Tafsiri T=0.2 (sahihi), Tafsiri Haraka T=0.4, Mwandishi wa Maudhui T=0.6 (ubunifu). Preset nyingine hutumia joto moja lililowekwa kwa vipengele vyote.','Technical / Scientific instructions'=>'Maagizo ya Kiufundi / Sayansi','Legal / Compliance instructions'=>'Maagizo ya Kisheria / Uzingatiaji','Creative / Marketing instructions'=>'Maagizo ya Ubunifu / Masoko','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Acha tupu ili kutumia chaguo-msingi cha kujengwa ndani. Kufuta chaguo lililohifadhiwa kunarudisha chaguo-msingi wakati wa hifadhi inayofuata.','View built-in default'=>'Tazama chaguo-msingi cha kujengwa ndani','Automatic Translation Backfill'=>'Kujaza Tafsiri Otomatiki','Periodically scans for posts missing a translation in an active language and queues an AI translation for each gap found — the same recovery you can already trigger by hand via "Translate missing" or the WP-CLI missing_translations/fill_translations commands, run automatically once an hour instead.'=>'Hupiga kelele kwa kawaida kwa ajili ya chapisha kupoteza tafsiri katika lugha yenye kazi na kuweka AI tafsiri kwa ajili ya kila pengo lililotaka — furaha hiyo sawa ambayo unaweza kufanya badala hiyo kwa mkono kupitia "Tafsiri kupoteza" au amri za WP-CLI missing_translations/fill_translations, ziendeshwe otomatiki mara moja kwa saa badala.','Automatic backfill'=>'Kujaza otomatiki','Automatically translate posts missing a language version'=>'Tatamka otomatiki chapisha kupoteza toleo la lugha','Off by default. This feature makes AI provider requests — and spends the associated API cost — automatically and in the background, with no per-request confirmation, for every published post found without a translation in an active language. Turn this on only if you want every content gap translated unattended; otherwise use "Translate missing" or the WP-CLI commands to translate on your own schedule.'=>'Imezimwa kwa chaguo-msingi. Kipengele hiki kinafanya ombi la mtoa huduma wa AI — na kutumiaji gharama inayohusiana na API — otomatiki na nyumba, bila uthibitisho kwa ombi kwa ombi, kwa kila chapisha kilichochapishwa kilichopatikana bila tafsiri katika lugha yenye kazi. Washa hii tu ikiwa unataka kila pengo la maudhui kutatamka bila msaada; kama si hivyo tumia "Tafsiri kupoteza" au amri za WP-CLI kutatamka kwa ratiba yako mwenyewe.','WooCommerce products and variations are never included, regardless of this setting. An integration can also block specific post types via the linguaforge_cpt_create_allowed filter.'=>'Bidhaa za WooCommerce na tofauti hazijajumuishwa kamwe, bila kujali mpangilio huu. Ujumuishaji unaweza pia kuzuia aina mahususi za chapisho kupitia kichujio cha linguaforge_cpt_create_allowed.','Comment Translation'=>'Tafsiri ya Maoni','Mirrors an approved comment onto every language version of the post it belongs to, translated, as a real comment on each sibling page. Off by default.'=>'Inakidhi maoni yaliyoidhinishwa kwenye kila toleo la lugha la chapisho linalohusiana, likiwa limewekwa kama maoni halisi kwenye kila ukurasa wa ndugu. Imezimwa kwa asili.','Comment translation'=>'Tafsiri ya maoni','Enable comment translation'=>'Wezesha tafsiri ya maoni','Off by default. This feature makes AI provider requests — and spends the associated API cost — for approved comments on any post that has translated language versions. WooCommerce product reviews are never included; they already share one review pool across languages.'=>'Imezimwa kwa asili. Kipengele hiki kinafanya maombi kwa mtoa huduma wa AI — na kinatumia gharama ya API inayohusiana — kwa maoni yaliyoidhinishwa kwenye chapisho lolote linalokuwa na matoleo ya lugha yaliyotafsiriwa. Mapitio ya bidhaa za WooCommerce hayatashirikishwa kamwe; tayari yanashiriki kikundi kimoja cha mapitio kati ya lugha.','Translation trigger'=>'Kichocheo cha tafsiri','Manual — translate only via the Comments screen action'=>'Mkononi — tafsiri tu kupitia hatua ya skrini ya Maoni','Automatic — translate every comment as soon as it\'s approved'=>'Automa — tafsiri kila maoni mara tu yanapothibitishwa','Manual (default) queues nothing automatically — use the "Translate missing" bulk action on the Comments screen on your own schedule. Automatic queues a translation the moment a comment is approved (or arrives already-approved), which can spend API calls on comments a moderator was about to reject if there\'s a large held-for-moderation backlog.'=>'Mkononi (kiwandani) haipangi chochote kiotomatiki — tumia hatua ya wingi "Tafsiri zipunguzwe" kwenye skrini ya Maoni kwa ratiba yako mwenyewe. Automa hupanga tafsiri mara tu maoni yanapothibitishwa (au kuwasili tayari yameidhinishwa), ambayo inaweza kutumia wito za API kwenye maoni ambayo mdhibiti alikuwa karibu kuyakataa ikiwa kuna uhifadhi mkubwa wa maoni yanayosubiri kudhibitiwa.','Max nested-reply depth'=>'Max kina cha jibu lililo ndani','How many levels of nested replies "Translate missing" will walk and translate in one pass, counting the original top-level comment as level 0. Default 2 covers the original comment plus replies and replies-to-replies. Bounds AI spend on deep threads — anything nested deeper isn\'t backfilled until this is raised or a further pass runs.'=>'Ni viwango vingapi vya majibu yaliyo ndani "Tafsiri zipunguzwe" vitaenda na kutafsiri kwa mpito mmoja, ikihesabu maoni ya awali kama kiwango 0. Kiwango cha 2 kinashughulikia maoni ya asili pamoja na majibu na majibu kwa majibu. Inapunguza matumizi ya AI kwenye nyuzi za kina — chochote kilicho ndani zaidi hakitawezeshwa hadi hii ipandishwe au kupita zaidi kufanywa.','The "Sync" button in the post list Lang column retranslates a post out into every other language, including the primary/source post when it\'s run from a translation. That back-translation direction is restricted by default for every post type. (WooCommerce products and variations have their own separate setting below — this one does not affect them.)'=>'Kitufe cha "Synchronize" katika orodha ya chapisho Lang safu inatamka chapisho kutoka kwa kila lugha jingine, ikiwemo chapisho cha msingi/chanzo wakati kiendeshwa kutoka kwa tafsiri. Mwelekeo huo wa back-translation unazuiwa kwa chaguo-msingi kwa kila aina ya chapisho. (Bidhaa za WooCommerce na tofauti zina mpangilio wao binafsi tofauti chini — hii haiathiri.','Secondary-language Sync'=>'Synchronize ya Lugha ya Upili','Allow "Sync" on a translated post to overwrite the primary post'=>'Ruhusu "Synchronize" katika tafsiri kuandika upya chapisho cha msingi','Off by default: clicking "Sync" on a translation is blocked from overwriting the primary post. Syncing FROM the primary post to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Imezimwa kwa chaguo-msingi: kubofya "Synchronize" katika tafsiri imezuiwa kutokuandika upya chapisho cha msingi. Kukamatia KUTOKA kwa chapisho cha msingi kwa kila tafsiri daima inaruhusiwa bila kujali mpangilio huu. Washa hii tu ikiwa unataka kweli tafsiri iweze kuwa chanzo kipya cha maudhui.','The primary-language product is WooCommerce\'s operational source of truth for price, SKU, and stock, which are always served from it regardless of which language a shopper is viewing. This is a separate, independent setting from the general "Sync" restriction above — enabling one does not enable the other.'=>'Bidhaa ya lugha ya msingi ni chanzo cha kazi cha WooCommerce cha ukweli kwa bei, SKU, na hazina, ambazo zinakupiwa kila wakati kutoka kwa hii bila kujali lugha ambayo kamata anahangaiko kuona. Hii ni mpangilio tofauti, wenye kazi, kutoka kwa vizuizi vya jumla "Synchronize" hapo juu — kuamilisha moja haiamilishi nyingine.','Allow "Sync" on a translated product to overwrite the primary product'=>'Ruhusu "Synchronize" katika bidhaa iliyotafsiriwa kuandika upya bidhaa ya msingi','Off by default: clicking "Sync" on a translated WooCommerce product is blocked, since it would back-translate onto the primary product\'s title, description, and excerpt. Syncing FROM the primary product to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Imezimwa kwa chaguo-msingi: kubofya "Synchronize" katika bidhaa ya WooCommerce iliyotafsiriwa imezuiwa, kwa sababu ingeinua back-translate kwenye kichwa cha bidhaa ya msingi, maelezo, na muhtasari. Kukamatia KUTOKA kwa bidhaa ya msingi kwa kila tafsiri daima inaruhusiwa bila kujali mpangilio huu. Washa hii tu ikiwa unataka kweli tafsiri iweze kuwa chanzo kipya cha maudhui.','General'=>'Jumla','Light'=>'Nuru','Meta Description, Excerpt Generator, quick translate'=>'Maelezo ya Meta, Kizazi cha Muhtasari, tafsiri ya haraka','Quality'=>'Ubora','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Tafsiri ya ukurasa kamili, Kizazi cha Maudhui (mifano ya kati ni ya kutosha kabisa)','Active Provider'=>'Mtoa huduma wa Sasa','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Kwa sasa urithi kutoka kwa kifungo cha %s. Kuchagua thamani hapa kutaleta mabadiliko.','WordPress AI Client — requirements:'=>'Mteja wa AI wa WordPress — mahitaji:','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>'Tafsiri ya kurasa kamili hutumia matokeo yaliyo na muundo wa JSON-schema. Hii inahitaji kiambatishi cha kiunganishi kusakinishwa na kuwa hai (si tu funguo ya API iliyohifadhiwa katika Settings → Connectors). Ikiwa tafsiri inashindwa, angalia kumbukumbu za makosa za PHP kwa kosa maalum, au badilisha kwa mtoa huduma aliyejengewa ndani.','Manage your account, review usage, or top up credits:'=>'Simamia akaunti yako, hakiki matumizi, au ongeza salio:','WordPress Connectors'=>'Viunganishi vya WordPress','Models'=>'Miundo','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Vipengele vimegawanywa katika ngazi mbili. Ingiza kitambulisho halisi cha mfano kwa kila ngazi na mtoa huduma. Acha uwanja tupu ili kutumia chaguo-msingi cha ndani (kinachoonyeshwa kama nafasi ya kujaza). Mifano ya mtoa huduma anayeendesha pekee ndiyo inaitwa wakati wa runtime — weka zingine mapema ikiwa unakusudia kubadilisha.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Anza kuandika katika uwanja wowote ili kuona mapendekezo ya modeli, au tumia jedwali la rejea hapo chini. Models za Ubora wa mwanga na wa kati (Haiku, GPT-4o mini, Gemini Flash) ni kamilifu kwa uhamishaji wa maudhui na uzalishaji — modeli kuu "max" huongeza gharama na ubora mdogo wa ziada kwa maandishi yaliyopangwa.','active'=>'kinachofanya kazi','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>'Uchaguzi wa mfano unasimamiwa na WordPress katika %s — hakuna kitambulisho cha mfano kinachohifadhiwa na Lingua Forge kwa mtoa huduma huyu.','overridden'=>'kimezuiwa','Translates a short sample of your most recent published post with this exact model — a real, billed API call.'=>'Inatamka sampuli fupi ya chapisho lako la hivi karibuni liliochapishwa na muundo huu halisi — simu halisi, simu iliyobofywa.','Test model'=>'Mtihani wa mtindo','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: ili kurejesha mfano kwa chaguo-msingi cha ndani, safisha uwanja na hifadhi.','Available models reference'=>'Rejeo la mifano inayopatikana','Model ID'=>'Kitambulisho cha Modeli','Name'=>'Jina','Tier'=>'Ngazi','Notes'=>'Maelezo','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Orodha hii huasisiwa na kila toleo la Lingua Forge. Kupima muunganisho kwenye kichupo cha Funguo za API pia kunapata orodha ya modeli hai kutoka kwa mtoa huduma na kuboresha mapendekezo hapo juu.','Glossary'=>'Kamusi','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Jedwali la istilahi linaloswa na mtumiaji kwa kila lugha. Viingilio vinaongezwa kwenye maelekezo ya mfumo wa tafsiri ili AI itumie maneno yanayopendelewa kwa utaratibu — muhimu kwa msamiati wa sekta ("kWp", "PPA", "sehemu ya kuunganishwa"), majina ya chapa ambayo hayapaswi kutafsiriwa, na maneno ya kanuni za udhibiti zilizowekwa. Sehemu zote za lugha ni hiari: acha "Lugha ya Chanzo" tupu ili kutumia kiingilio bila kujali unapotafsiri kutoka kwa lugha gani; acha "Lugha ya Malengo" tupu ili kuitekeleza kwa lugha zote za malengo kwa pamoja.','Glossary entry added.'=>'Kuingiza kamusi ya msamiati kumetokea.','Glossary entry removed.'=>'Kufuta kamusi ya msamiati.','Could not add entry: source term and target term are required.'=>'Haiwezi kuongezea kiingilio: neno la chanzo na neno la malengo linahitajika.','Could not save the glossary entry.'=>'Haiwezi kuokoa kiingilio cha kamusi ya msamiati.','Source language'=>'Lugha ya Chanzo','— Any —'=>'— Yoyote —','Target language'=>'Lugha ya Malengo','— Any target —'=>'— Malengo yote —','Filter'=>'Kichujio','Reset'=>'Washa upya','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Hakuna viingilio vya kamusi vinavyolingana na kichujio cha sasa. Futa kichujio ili kuona viingilio vyote, au ongeza kiingilio kipya chini.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Hakuna viingilio vya kamusi bado. Weka chini ili kuanza kutekeleza istilahi katika tafsiri.','Source term'=>'Neno la Chanzo','Target term'=>'Neno la Malengo','Source lang'=>'Lugha ya Chanzo','Target lang'=>'Lugha ya Malengo','any'=>'yote','Delete this glossary entry?'=>'Unataka kufuta kiingilio hiki cha kamusi? ','Add new entry'=>'Ongeza kiingilio kipya','The phrase as it appears in the source text.'=>'Sehemu kama ilivyoonekana katika maandishi ya chanzo.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Jinsi inapaswa kuonekana katika tafsiri. Andika thamani ile ile na neno la chanzo ili kuagiza AI kuilinda kwa maneno halisi.','— Any source language —'=>'— Yoyote ya lugha ya chanzo —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Acha tupu kwa majina ya chapa na maneno yasiyotegemea lugha ambayo yanapaswa kutekelezwa bila kujali lugha tunayotafsiri kutoka.','— Any target language —'=>'— Yoyote ya lugha ya malengo —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Acha tupu ili kiingilio hiki kiweze kutumika kwa lugha zote za malengo — bora kwa majina ya chapa, kifupi, na maneno yanayopaswa kuhifadhiwa kwa maneno halisi katika kila tafsiri.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Muktadha wa hiari kwa wahariri (kama vile "ASIC = Circuit ya Maombi Mahususi; ihifadhi kwa Kiingereza katika muktadha wa kiufundi").','Add entry'=>'Ongeza kiingilio','Limits'=>'Mipaka','Authors and above (edit_published_posts)'=>'Waandishi na zaidi (hariri_maandishi_yaliyochapwa)','Contributors and above — default (edit_posts)'=>'Wachangia na zaidi — chaguo-msingi (hariri_maandishi)','Editors and above (edit_others_posts)'=>'Wahariri na zaidi (hariri_wa_waandishi_wengine)','Administrators only (manage_options)'=>'Wasimamizi pekee (simamia_mipangilio)','AI Limits & Security'=>'Mipaka na Usalama wa AI','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Kataza kiasi cha matumizi ya AI kinachoweza kuzalishwa na tovuti na kuzuia majukumu ya watumiaji wanaoweza kuanzisha simu za AI zilipwa. Inachukua nafasi ya kikomo cha kila mtumiaji (ombi 30 / dakika, kilichowekwa kwa nguvu) kinacholinda dhidi ya mizunguko ya kipekee ya mtumiaji.','Daily request limit'=>'Kikomo cha maombi ya kila siku','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Kikomo cha tovuti kwa maombi ya AI kwa siku ya UTC (kinahesabu tafsiri za Zana na marekebisho ya kizuizi). Kiwango kinarejeshwa saa sita usiku wa UTC. Weka 0 ili kuzima kikomo.','Minimum role'=>'Hali ya chini','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Uwezo wa WordPress wa chini kabisa unaoruhusiwa kuanzisha vipengele vya AI. Kuimarisha hili kwenye tovuti za waandishi wengi kunazuia Wachangia au akaunti za majaribio kuendesha simu za AI zilipwa. Pitia kwa kila kipengele kupitia kichujio cha "linguaforge_required_capability".','Translation Limits'=>'Mipaka ya Tafsiri','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Dhibiti kiasi cha maudhui yanayopitishwa kwa AI na ukubwa wa majibu yanayoweza kutolewa. Acha uwanja tupu ili kutumia chaguo-msingi cha ndani (kinachoonyeshwa kama mahali pa kuweka). Ongeza thamani hizi ikiwa kurasa kubwa zinakatwa; punguza ili kupunguza gharama za API.','Model tier'=>'Kiwango cha mfano','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Ubora (chaguo-msingi — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Mwanga (haraka na nafuu — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Kiwango cha mfano kinachotumika kwa tafsiri ya kurasa kamili. Ubora unatumia mfano uliowekwa kwenye jedwali la Miundo hapo juu na ni wa kupendekezwa kwa tafsiri sahihi, ya muda mrefu. Badilisha kwa Mwanga ikiwa ni haraka au gharama ndogo ndogo ndizo kipaumbele na maudhui ni mafupi.','Max output tokens'=>'Idadi ya tokeni za matokeo makubwa','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Idadi kubwa ya tokeni ambazo AI inaweza kuzalisha kwa jibu moja la tafsiri. Ikiwa tafsiri inakatwa kimya kimya mwisho, ongeza thamani hii. Chaguo-msingi: 16,000.','Max input characters'=>'Herufi za ingizo za juu zaidi','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Kiwango kikubwa cha wahusika wa maudhui ya chapisho yaliyotumwa kwa AI. 0 inamaanisha hakuna kikomo — maudhui kamili yanatumiwa daima (inapendekezwa). Weka thamani isiyo sifuri ikiwa mtoa huduma wako ana dirisha la muktadha mkali. Onyo linaandikwa kwenye kumbukumbu ya makosa ya PHP kila wakati maudhui yanapunguzwa.','Quick Translation'=>'Tafsiri Haraka','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Tafsiri Haraka hutumiwa kwa hali ya vipande/vipande — vifungu vifupi vinavyotafsiriwa kwa ombi kutoka kwa upau wa zana, mhariri, au popo za kizuizi. Inatumia usanidi tofauti, nyepesi kutoka kwa tafsiri ya ukurasa kamili ili kuweka majibu kuwa ya haraka na yenye gharama nafuu.','Light (default — fast and cost-effective)'=>'Nuru (chaguo-msingi — haraka na yenye gharama nafuu)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Ubora (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Kiwango cha Nuru kinatumia mfano wa haraka uliowekwa kwenye jedwali la Miundo hapo juu (chaguo-msingi: Haiku / Flash). Badilisha kwa Ubora ikiwa unahitaji usahihi wa tafsiri sawa na hali ya ukurasa kamili kwa vipande.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Wahusika wa juu zaidi wanaowezekana na AI inaweza kuzalisha kwa kila tafsiri ya haraka. Chagua: 2,000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Wahusika wa juu zaidi wanaokubaliwa kutoka kwa uwanja wa ingizo. Chaguo-msingi: 8,000.','Content Generator'=>'Kizazi cha Maudhui','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Hudhibiti bajeti ya tokeni na mipaka ya ingizo kwa kipengele cha Kizazi cha Maudhui cha AI. Acha mashamba tupu ili kutumia chaguo-msingi zilizojengwa ndani.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Wahusika wa juu zaidi wanaowezekana na AI wanaweza kuzalisha kwa kila uendeshaji wa kizazi. Ongeza ikiwa makala kamili yanakatwa. Chaguo-msingi: 8,192.','Max hints characters'=>'Wahusika wa vidokezo vya juu zaidi','Maximum characters read from the Hints field. Default: 2 000.'=>'Wahusika wa juu zaidi wanaosomwa kutoka kwa uwanja wa Vidokezo. Chaguo-msingi: 2,000.','Max context characters'=>'Wahusika wa muktadha wa juu zaidi','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Wahusika wa juu zaidi wa maudhui ya chapisho yaliyopo yanayotumwa kwa AI kama muktadha wa mbegu wakati hakuna Vidokezo vinavyotolewa. Chaguo-msingi: 6,000.','Maintenance'=>'Matengenezo','Router'=>'Router','Primary language saved.'=>'Lugha kuu imehifadhiwa.','Permalink rules flushed successfully.'=>'Sheri za permalink zimefutwa kwa mafanikio.','Language uninstalled. %d post deleted.'=>'Lugha imeondolewa. Chapisho %d kimefutwa.' . "\0" . 'Lugha imeondolewa. Machapisho %d yamefutwa.','%d locale file removed.'=>'Faili %d za lugha zimetolewa.' . "\0" . 'Faili %d za lugha zimetolewa.','%d pattern translation removed.'=>'%d tafsiri ya muundo iliyoondolewa.' . "\0" . '%d tafsiri za muundo zilizondolewa.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'Faili %d za lugha haziwezi kufutwa kiotomatiki (DISALLOW_FILE_MODS imewashwa). Futa kwa mikono kupitia seva yako au WP-CLI: wp language core uninstall <locale>.' . "\0" . 'Faili %d za lugha haziwezi kufutwa kiotomatiki (DISALLOW_FILE_MODS imewashwa). Futa kwa mikono kupitia seva yako au WP-CLI: wp language core uninstall <locale>.','Primary Language'=>'Lugha Kuu','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Lugha kuu daima hutumika kwenye mzizi wa tovuti yako — hakuna kiambishi cha URL katika hali ya njia, hakuna subdomain ya lugha katika hali ya subdomain. Lugha nyingine zote hutumia au kiambishi cha /lang/ (mfano example.com/de/) au subdomain ya lugha (mfano de.example.com), kulingana na mpangilio wa muundo wa URL hapo chini.','Primary language'=>'Lugha kuu','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Baada ya kubadilisha lugha kuu, safisha permalink (sehemu chini) ili kusasisha njia ya URL.','Path prefix — example.com/de/'=>'Kipindi cha njia — example.com/de/','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Mode ya subdomain inahitaji seva yako ya wavuti kuelekeza subdomains zote za lugha (kama de.example.com) kwa usakinishaji huu wa WordPress. Baada ya kubadilisha mode, fanya usafi wa sheria za permalink na safisha cache yoyote. Ikiwa URL yako ya nyumbani inajumuisha www (kama www.example.com), tumia kichujio cha lf_base_domain kuweka domain kuu bila www ili subdomains zifanywe kwa usahihi.','Browser language redirect'=>'Uelekeaji wa lugha wa kivinjari','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Uelekeza wageni kwa lugha yao wanayoipendelea kulingana na kichwa cha Accept-Language cha kivinjari','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Wakati kinachozimwa, wageni wa mara ya kwanza wasio na keki ya lugha na bila kiambishi cha lugha kwenye URL wanapelekwa kwa toleo la lugha linalolingana zaidi. Uelekezaji huachwa ikiwa lugha inayopendelewa na kivinjari si miongoni mwa lugha zinazofanya kazi za router. Mara mgeni anapochagua lugha kupitia kisakinishi, keki inachukua kipaumbele na kichwa cha kivinjari hakitazingatiwa kwa ziara zijazo.','Query Filter Exclusions'=>'Kujumuisha kwa Kichujio cha Maswali','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge inazingatia nakala za WP_Query za pili (vidirisha vya upande, vijiti vya template, utafutaji wa programu-jalizi) kwa lugha hai kwa kuingiza vigezo vya meta _lf_lang. Aina za machapisho zilizoorodheshwa hapa hazijumuishwi na vigezo hivyo — maswali yao daima hayajachujwa.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Fomu ya Mawasiliano 7 (wpcf7_contact_form), mawasiliano ya Flamingo na ujumbe wa kuingia (flamingo_contact, flamingo_inbound), na usawazishaji wa pakiti la lugha la WordPress (wp_sync_storage) yanachukuliwa kiotomati. Ongeza aina nyingine za machapisho za watu wa tatu ambazo maudhui yao hayapaswi kupitiwa kwa lugha, moja kwa mstari au kwa koma.','Excluded post types'=>'Aina za machapisho zilizozuiwa','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Majina ya aina ya chapisho yanayotenganishwa kwa koma au mistari mipya. Mabadiliko yanachukua athari mara moja wakati wa kuhifadhi — hakuhitaji kufuta permalink.','WooCommerce Integration'=>'Ujumuishaji wa WooCommerce','Controls how Lingua Forge integrates with WooCommerce order processing.'=>'Hii inaamua jinsi Lingua Forge inavyoshirikiana na usindikaji wa oda za WooCommerce.','Order line item source mapping'=>'Ramani ya chanzo cha kipengee cha orodha ya agizo','Normalize order line item product IDs to the source-language product at checkout'=>'Sanifu nambari za bidhaa za orodha ya agizo kwa bidhaa ya lugha asili wakati wa malipo','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>'Wakati umewezeshwa (inapendekezwa), ID ya bidhaa iliyohifadhiwa kwenye kila kipengee cha agizo cha WooCommerce huwekwa kwenye bidhaa ya lugha asili. Hii inahakikisha hesabu za mauzo kamili, safu za mapato za WC Analytics, na usafirishaji wa ERP wa mtu wa tatu unarejelea ID moja ya bidhaa kwa SKU badala ya moja kwa kila toleo la lugha. Mabadiliko: viungo vya "Tazama bidhaa" kwenye barua pepe za agizo na Akaunti Yangu hupelekea ukurasa wa lugha asili. Zima tu ikiwa mfumo unaounganishwa unategemea IDs za bidhaa zilizotafsiriwa kwenye maagizo. Tumia kichujio cha linguaforge_wc_order_item_source_mapping kwa mabadiliko ya kila kipengee.','Save Router Settings'=>'Hifadhi Mipangilio ya Router','Flush Permalinks'=>'Fanya usafi wa Permalinks','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Inarejesha sheria za uandishi wa WordPress ili viambishi vya URL, slug za lugha, na uandishi wa makala viwe vinaendana. Inahitajika baada ya kubadilisha lugha kuu au kuongeza msaada wa lugha mpya.','Flush Permalink Rules'=>'Fanya usafi wa Sheria za Permalink','Active Languages'=>'Lugha Zinazotumika','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Lugha zinazojulikana kwa sasa kwa router (zinatokana na pakiti za lugha za WordPress zilizowekwa pamoja na lugha kuu). Weka pakiti za lugha za ziada katika sehemu iliyo chini ili kufanya lugha zaidi zipatikane kwa uelekezaji na tafsiri.','%d locale pack installed.'=>'%d pakiti za lugha zimewekwa.' . "\0" . '%d pakiti za lugha zimewekwa.','Install a Language'=>'Sakinisha Lugha','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Pakua na usakinishe pakiti ya lugha kuu ya WordPress moja kwa moja kutoka WordPress.org. Mara baada ya kusakinisha, lugha inapatikana kwa uelekezaji wa URL na mchakato wa tafsiri wa AI. Orodha ya lugha zinazopatikana inachukuliwa kwa ombi — bofya kitufe chini ili kuipakua.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Sakinisho la lugha limezimwa kwenye seva hii. Kigezo cha DISALLOW_FILE_MODS kimewekwa katika wp-config.php. Sakinisha pakiti za lugha kwa mikono kupitia WP-CLI: wp language core install de_DE','Load available languages'=>'Pakua lugha zinazopatikana','— select a language —'=>'— chagua lugha —','Install'=>'Sakinisha','Language Setup'=>'Mipangilio ya Lugha','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Hakuna lugha za ziada zilizowekwa. Sakinisha pakiti ya lugha hapo juu ili kuwezesha muundo wa kiolezo.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Chagua lugha ili kuendesha muundo wa FSE, sehemu za muundo, na menyu za urambazaji.','Recreate All Languages'=>'Tengeneza Upya Lugha Zote','Recreate All Languages (Templates Only)'=>'Tengeneza Upya Lugha Zote (Violezo Tu)','Recreate All Languages (Template Parts Only)'=>'Tengeneza Upya Lugha Zote (Sehemu za Violezo Tu)','Cancel'=>'Ghairi','Repair Template Metadata'=>'Rekebisha Metadata ya Template','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Inarekebisha jina la eneo la Mhariri wa Tovuti na lebo _lf_lang kwenye templates zote za FSE zilizoandaliwa na LF zilizohifadhiwa kwenye hifadhidata. Endesha hii mara moja baada ya kusasisha kutoka toleo la awali la Lingua Forge — inahamisha templates zinazotokana na WooCommerce kutoka kwa kundi la mandhari hai hadi kundi la WooCommerce kwenye Mhariri wa Tovuti, na kuhakikisha templates zote zilizojengwa zinaweza kupatikana kwa ripoti za ufanisi.','Repair template metadata'=>'Rekebisha metadata ya template','Request failed.'=>'Ombi limekosewa.','Forbidden'=>'Kizuizi','Danger Zone'=>'Eneo la Hatari','Uninstall %s'=>'Futa %s','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Futa kwa kudumu mifano yote, sehemu za mifano, mifano, menyu za urambazaji, machapisho, kurasa, aina maalum za machapisho, bidhaa, na mabadiliko ya bidhaa yanayohusiana na lugha hii. Pia huondoa faili za pakiti za lugha ya WordPress ili lugha hii isiweze kuonekana tena kwenye router. Hatua hii haiwezi kurudishwa nyuma.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Lugha hii inalingana na eneo la WordPress na haiwezi kufutwa.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Futa kwa kudumu %s? Hii itafuta maudhui yote yaliyotafsiriwa kwa lugha hii na haiwezi kurudishwa nyuma.','Invalid language code.'=>'Msimbo batili wa lugha.','This language is protected and cannot be uninstalled.'=>'Lugha hii inalindwa na haiwezi kufutwa.','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Sakinisho la lugha limezimwa kwenye seva hii (DISALLOW_FILE_MODS imewekwa).','Invalid locale code.'=>'Msimbo wa lugha si sahihi.','Language %s installed successfully.'=>'Lugha %s imewekwa kwa mafanikio.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Sakinisho la pakiti ya lugha limegonga. Lugha inaweza tayari imewekwa, msimbo wa lugha si sahihi, au seva yako inazuia uandishi wa faili.','Navigations'=>'Viongozi','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Utaratibu wa urambazaji unahitaji mtoa huduma wa AI anayeishi. Sanidi ufunguo wa API kwenye kichupo cha Funguo za API.','Navigation'=>'Urambazaji','Re-translate'=>'Tafsiri tena','CPT Block Patterns'=>'Mipango ya Block CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Mipango ya block zilizoorodheshwa kwa aina za machapisho maalum. Tumia kitufe cha Tafsiri kuunda toleo la lugha. Yaliyomo yaliyotafsiriwa yanahifadhiwa hapa na yanaweza kuhamishwa kwenye chapisho lolote la CPT kutoka kwa mhariri wa block au kutumika kama hatua ya kuanzia kwa Pattern iliyosawazishwa (Reusable Block).','Pattern'=>'Mfano','Post Types'=>'Aina za Machapisho','✓ Translation saved'=>'✓ Tafsiri imehifadhiwa','View'=>'Tazama','Template Parts'=>'Sehemu za Muundo','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Nakili za lugha maalum za mandhari. Mara baada ya kuundwa, templates huboreshwa kurejelea sehemu maalum za lugha.','Re-create all'=>'Tengeneza upya zote','Translate all'=>'Tafsiri zote','Fix all links'=>'Rekebisha viungo vyote','Fix all navs'=>'Rekebisha mitandao yote','Part'=>'Sehemu','Status / Actions'=>'Hali / Vitendo','Create'=>'Unda','Templates'=>'Mifano','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Mifano ya FSE iliyopandikizwa kutoka kwa mandhari hai. Unda kisha ibadilike kwenye Mhariri wa Tovuti.','Create missing'=>'Unda zilizokosewa','Fix all parts'=>'Rekebisha sehemu zote','SEO'=>'SEO','Multilingual SEO'=>'SEO ya Lugha Nyingi','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Sanidi hreflang, Open Graph, Schema.org, ramani za tovuti, na ushirikiano wa kijamii kwa kila lugha kwenye tovuti yako. Sehemu kila chini inashughulikia kipengele kimoja cha SEO ya lugha nyingi.','Open Graph &amp; Twitter Cards'=>'Kadi za Open Graph &amp; Twitter','Schema.org'=>'Schema.org','Sitemap'=>'Ramani ya Tovuti','Analysis'=>'Uchambuzi','Compatibility'=>' Ulinganifu','System'=>'Mfumo','Overview'=>'Muhtasari','Lingua Forge Settings'=>'Mipangilio ya Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge huongeza mwelekeo wa lugha nyingi, tafsiri yenye nguvu ya AI, tags za SEO za hreflang, na kisakinishi cha lugha kwenye tovuti yako ya WordPress.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Tumia kanda za juu za ukurasa huu kuunda kila eneo. Mabadiliko kwenye kanda ya Router yanachukua athari mara moja; mabadiliko kwenye funguo za AI na mipangilio ya mfano yanahusiana na ombi lijalo la AI.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Baada ya kubadilisha mipangilio ya muundo wa URL (kianzio cha njia ↔ subdomain), daima tembelea Mipangilio → Permalinks na bofya Hifadhi Mabadiliko ili kufuta sheria za kuandika upya.','AI Provider Tab'=>'Kipengele cha Mtoa Huduma wa AI','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Watoa huduma wanaounga mkono: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Chagua mtoa huduma hai kutoka kwenye orodha — mtoa huduma mmoja tu hutumika kwa wakati mmoja. Ingiza ufunguo wa API kwa mtoa huduma huo ili kuwezesha vipengele vya AI.','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Funguo zimefungwa kwa usalama kwa kutumia AES-256-GCM na siri maalum ya tovuti (LINGUAFORGE_SECRET). Usishiriki usafirishaji wa hifadhidata bila kubadilisha siri kwanza.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Vipengele vya AI ni hiari. Mwelekeo wa lugha, hreflang, kisakinishi cha lugha, na mfumo wa kikundi cha tafsiri vyote vinafanya kazi bila mtoa huduma aliyesakinishwa.','Model tiers'=>'Viwango vya mfano','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge hutumia safu mbili za mfano kwa kila mtoa huduma:','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Nuru: inatumika kwa maelezo mafupi na uzalishaji wa excerpt — haraka, gharama ya chini.','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Ubora: hutumika kwa tafsiri ya chapisho na uzalishaji wa maudhui — ubora wa juu, gharama ya juu.','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Acha uwanja wa mfano ukiwa tupu ili utumie chaguo-msingi cha ndani kwa kiwango hicho. Maandishi ya placeholder yanaonyesha mfano wa mfano utakaotumika.','Translation Limits & Behavior'=>'Mipaka ya Tafsiri & Tabia','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Mipaka ya Tafsiri: kudhibiti ni majukumu ya aina gani za watumiaji wanaweza kuanzisha tafsiri ya AI, na kuweka bajeti ya token kwa mwezi. Kupita bajeti kunasababisha kusitisha simu za AI hadi mwezi ujao utakapobadilika.','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Tabia: chagua preset ya AI (Literal, Balanced, Creative), ongeza maagizo maalum ya tovuti kwa ujumla, wezesha au zima tafsiri ya otomatiki baada ya kuhifadhi chapisho, na weka kumbukumbu ya Tafsiri.','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Kumbukumbu za Tafsiri hufanya kazi kwa kuhifadhi matokeo ya AI kwa hash ya maudhui, jozi ya lugha, mtoa huduma, na mfano. Kuhariri chapisho kunavunjilia mbali kumbukumbu ili simu inayofuata ya tafsiri ipate matokeo mapya.','Router Tab'=>'Tabu ya Router','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Lugha kuu: lugha ambayo maudhui yako ya sasa yameandikwa. Tafsiri zote hutoka kwa lugha hii; kubadilisha hakusababishi kuhamisha au kufuta machapisho yoyote.','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Muundo wa URL: hali ya kiambatanisho cha njia (example.com/de/) hahitaji mabadiliko ya seva. Hali ya subdomain (de.example.com) inahitaji rekodi ya DNS ya wildcard, cheti cha SSL cha wildcard, na mabadiliko ya usanidi wa seva — angalia mwongozo wa Usanidi wa Seva.','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Lugha zinazotumika: ongeza kila lugha unayotaka kuunga mkono. Kila lugha hupata kiambatanisho cha URL au subdomain na lebo ya hreflang kwenye &lt;head&gt; ya ukurasa.','WP site language requirement'=>'Hitaji la lugha ya tovuti ya WP','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'Lugha ya tovuti ya WordPress (Mipangilio → Jumla → Lugha ya Tovuti) lazima iwe imewekwa kwa mojawapo ya lugha unazotumia kwa maudhui — au lugha kuu ya maudhui au mojawapo ya lugha za sekondari. Haiwezi kuwa lugha isiyo na maudhui kwenye tovuti.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Mfano wa usanidi unaounga mkono: Lugha ya tovuti ya WP = CA (Katalani), lugha za maudhui = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Mfano wa usanidi usioungwa mkono: Lugha ya tovuti ya WP = EN (Kiingereza), lugha za maudhui = CA + ES pekee. Kiingereza si lugha ya maudhui, kwa hivyo Lingua Forge haiwezi kuoanisha eneo la WP na kundi lolote la tafsiri.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'Wakati lugha ya tovuti ya WP si lugha ya maudhui: maswali ya bidhaa za WooCommerce yanarudisha matokeo sifuri kwenye bulo zote za katalogi; uwasilishaji wa picha za bidhaa unashindwa; maswali yote ya maudhui yaliyochaguliwa kwa lugha yanavunjika; kiendeshi lugha kinaweza kuonyesha chaguo cha lugha isiyo ya maudhui. Ikiwa unaona onyo nyekundu la usanidi kwenye juu ya Router au kichupo cha Mfumo, rekebisha lugha ya tovuti kwanza.','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Uwezo wa FSE: tengeneza, tafsiri, na rekebisha viungo katika templates za Full Site Editing na sehemu za templates moja kwa moja kutoka kwa tab hii.','Glossary Tab'=>'Tabu ya Kamusi','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Weka maneno ambayo hayapaswi kutafsiriwa au lazima yatangazwe kwa njia fulani (k.m. majina ya chapa, majina ya bidhaa, maneno mafupi). Mipaka ya kamusi huingizwa katika kila ombi la tafsiri la AI kwa ajili ya vipengele vyote: tafsiri ya chapisho, maelezo ya meta, excerpt, na tafsiri ya template ya FSE.','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Ongeza neno moja kwa kila mstari. Neno la chanzo na uwasilishaji wa lengo vinahitajika. Jozi ya lugha huamua kazi za tafsiri zinazotumika na masharti.','SEO Tab'=>'Kipengele cha SEO','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge ni suluhisho kamili la SEO lenye lugha nyingi. Hakuna plugin ya SEO au ramani ya tovuti inayohitajika.','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Kile LF hutoa: lebo za hreflang kwa kila lugha iliyowekwa, lebo za Open Graph na Twitter Card na og:locale na og:locale:alternate, Schema.org JSON-LD na maelezo ya inLanguage, na ramani ya tovuti maalum ya lugha nyingi kwenye /lf-sitemap.xml na viingilio mbadala vya xhtml:link kwa vikundi vyote vya tafsiri.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Ramani ya tovuti inatangazwa moja kwa moja katika robots.txt. Mengineyo makuu ya injini za utafutaji — Google, Bing, Yandex — yanagundua kutoka robots.txt. Hakuna uwasilishaji wa mkono unaohitajika.','SEO plugins and conflict avoidance:'=>'Programu-jalizi za SEO na kuepuka migongano:','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Ikiwa una SEO ya Yoast, Rank Math, All in One SEO, au SEOPress imewekwa, Lingua Forge huvitambua na kubadilika ili kuepuka matokeo ya kurudiwa. Kwa hreflang, LF inachukua udhibiti kabisa na kuzuia matokeo ya programu-jalizi kwa sababu programu-jalizi hizo haziwezi kuzalisha hreflang sahihi kwa usanidi wa mwelekeo wa lugha nyingi. Kwa Open Graph, LF huongeza tu og:locale na og:locale:alternate — ishara za lugha nyingi ambazo programu-jalizi haiwezi kutoa — na huacha seti ya OG ya msingi kwa programu-jalizi. Kwa Schema.org, LF huzimisha matokeo yake mwenyewe kabisa ili kuepuka michoro ya JSON-LD inayopingana.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Kipengele cha SEO → Ulinganifu kinatoa hali ya kugundua moja kwa moja na kinaelezea hasa LF inafanya nini kwa kila eneo la kipengele.','SEO Scores'=>'Alama za SEO','SEO Score System'=>'Mfumo wa Alama za SEO','Score computation'=>'Hisabati ya alama','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Kila chapisho kinapimwa 0–100 kutoka kwa vigezo sita vinavyotegemea sheria: kichwa, maelezo ya meta, idadi ya maneno, muundo wa vichwa vya habari, ufunuo wa picha, na viungo vya ndani. Pointi kumi daima hapatikana kwa wakati wa kusoma (taarifa tu). Pointi 90 zilizobaki zinagawanywa kwa vigezo vingine kwa uzito unaobadilika kulingana na profaili ya maudhui (angalia chini).','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Kila kipimo hutoa mojawapo ya hali nne: sawa (uzito kamili), onyo (50 % ya uzito), kushindwa (0), au taarifa (0, hakuna adhabu). Alama ≥ 80 ni ya kijani, 50–79 ni ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi ya rangi.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Kanuni za alama za kichwa (profaili zote): kushindwa ikiwa tupu; onyo ikiwa chini ya herufi 10; onyo ikiwa ni neno moja tu; onyo ikiwa ni zaidi ya kikomo cha SERP cha profaili (60 herufi kwa Blog, 70 kwa Bidhaa/Ukuta); sawa ikiwa angalau herufi 10, angalau maneno 2, na ndani ya kikomo cha SERP.','Content profiles and weights'=>'Profaili za maudhui na uzito','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Profaili huendana na vigezo na uzito kulingana na aina ya maudhui yanayochambuliwa. Profaili huamuliwa kiotomatiki; unaweza kuibadilisha kwa kila uendeshaji wa uchambuzi kutoka kwa orodha ya profaili.','Blog / Editorial (default)'=>'Blogu / Mhariri (chaguo-msingi)','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Kichwa 15 pts · Maelezo ya Meta 20 pts · Idadi ya maneno 15 pts · Vichwa vya sehemu 20 pts · Picha 10 pts · Viungo 10 pts. Kiwango cha Kichwa cha SERP 60 herufi; meta 120–210 herufi; onyo la idadi ya maneno chini ya 300, kushindwa chini ya 100; H2 inahitajika; viungo vya ndani vinahitajika.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Imegunduliwa kiotomatiki kwa bidhaa za WooCommerce. Kichwa 20 pts · Maelezo ya Meta 30 pts · Idadi ya maneno 15 pts · Vichwa vya habari 5 pts · Picha 20 pts · Viungo 0 pts. Kiwango cha SERP cha Kichwa ni herufi 70; onyo la idadi ya maneno chini ya 80, kushindwa chini ya 40; H2 na viungo vya ndani ni hiari.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Imegunduliwa kiotomatiki kwa ukurasa wa mbele wa static; inaweza kuchaguliwa kwa mikono. Kichwa 20 pts · Maelezo ya Meta 30 pts · Idadi ya maneno 15 pts · Vichwa vya habari 10 pts · Picha 15 pts · Viungo 0 pts. Kiwango cha SERP cha Kichwa ni herufi 70; onyo la idadi ya maneno chini ya 150, kushindwa chini ya 60; H2 na viungo vya ndani ni hiari.','Heading structure rules'=>'Sheria za muundo wa vichwa vya habari','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'H1 moja tu inahitajika. H1 kwa kawaida ni kichwa cha chapisho kinachotolewa na mandhari — kinachotolewa kutoka kwa ukurasa ulioonyeshwa wa moja kwa moja wakati inawezekana, na kutoka kwa maudhui ya chapisho kama mbadala.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Wakati profaili ya Blog inahitaji H2 na hakuna inapatikana, mchanganuzi anachunguza kwanza vichwa vya H3 kabla ya kutoa onyo. Vipande vya Accordion na Details vinachagua H3 kwa vichwa vyao; H3 hizo zinakubalika kama muundo halali na husababisha matokeo mazuri, si onyo.','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'Maudhui mafupi (aya 3 au chini) hayalipwi kamwe kwa kukosekana kwa vichwa vya sehemu, bila kujali profaili. Ukurasa mfupi haufaidi muundo wa vichwa vya sehemu uliozidiwa.','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'Chukua H2 kama sawa na H1 (Mipangilio → SEO → Uchanganuzi): weka hii wakati mandhari yako inatoa kichwa cha chapisho ndani ya H2 badala ya H1. Mchambuzi huinua H2 ya kwanza hadi H1 ili alama isiadhibike vibaya.','Score history and badges'=>'Historia ya alama na nembo','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Kila wakati chapisho kinachanganywa alama inahifadhiwa kwenye meta ya chapisho. Orodha ya chapisho ina safu ya Lugha ina alama ya "SEO N" kwa chapisho chochote kilichochambuliwa angalau mara moja. Wakati alama mbili zinahifadhiwa, kiashirio cha mabadiliko (↑N / ↓N) kinaonyesha mabadiliko tangu mara ya awali.','AI Usage & Cache Tab'=>'Kipengele cha Matumizi ya AI & Cache','Token usage'=>'Matumizi ya Tokeni','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'Jedwali la matumizi linaonyesha matumizi ya token za AI zilizogawanywa kwa kipengele (tafsiri, maelezo ya meta, muhtasari, template ya FSE, uchambuzi wa kundi), mtoa huduma, na mfano. Tumia vitufe vya kipindi cha tarehe kuchuja kwa leo, siku 7 zilizopita, siku 30 zilizopita, au wakati wote.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'Kikomo cha kila siku (kinachopangwa katika Tabia → Mapungufu) kinarejelewa hapa. Wakati kikomo kinapofikiwa, simu za AI husitishwa kwa siku hiyo. Jedwali linaonyesha ni kiasi gani cha kikomo kime tumika.','Translation caching'=>'Kuhifadhi kwa njia ya tafsiri','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge inatumia safu mbili za kuhifadhi data kwa kujitegemea ili kupunguza simu za API za AI zinazojirudia:','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'Hifadhi majibu ya AI yaliyohifadhiwa kwa funguo kwa hash ya maudhui, jozi ya lugha, mtoa huduma, mfano, na preset. Vipengee vya cache vinavunjwa kiotomati wakati maudhui ya chapisho chanzo yanabadilika. Futa vitu vya chapisho binafsi au cache yote kutoka kwa kichupo hiki.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Hifadhi matokeo kamili ya chapisho kilichotafsiriwa kwa kila hash ya maudhui. Chagua (imewezeshwa katika Tabia). Inaharakisha tafsiri za mara kwa mara za maudhui yasiyobadilika. Futa hapa unapotaka kulazimisha mchakato mpya wa AI bila kujali kama maudhui yamebadilika.','Maintenance Tab'=>'Tabu ya Matengenezo','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Mabadiliko ya Lugha: simamia faili za mabadiliko maalum za .po/.mo kwa mistari ya UI ya Lingua Forge. Tumia hii badala ya kuhariri faili za programu moja kwa moja — mabadiliko yanadumu baada ya masasisho.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Kagua: wezesha rekodi ya kagua ili kukamata maombi ya AI na majibu ya API kwa faili la ndani. Zima baada ya utatuzi wa matatizo — hali ya kagua inaandika faili kwa kila ombi la AI.','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Tabia ya kufuta programu-jalizi: inaamua ni nini kinatoweka wakati programu-jalizi inafutwa kutoka kwa Programu-jalizi → Programu-jalizi zilizowekwa → Futa. Mipangilio ya programu-jalizi na cache za AI daima zinatoweka. Ugawaji wa lugha, uhusiano wa tafsiri, maelezo ya meta, kamusi, na Kumbukumbu ya Tafsiri zinahifadhiwa kwa chaguo-msingi ili kuzuia kufuta au kusakinisha upya kwa bahati mbaya kunaweza kuendelea mahali pa mwisho. Washa "Futa data ya maudhui wakati wa kufuta" tu wakati unatoa msaada wa lugha nyingi kwa tovuti — hii haiwezi kurejeshwa.','System Tab'=>'Kipengele cha Mfumo','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Uchunguzi wa haki ya kusoma pekee kwa usakinishaji wa sasa. Hakuna mipangilio inabadilishwa hapa — tumia kuangalia usanidi, kugundua matatizo, na kukusanya taarifa za ripoti za hitilafu.','Sections'=>'Sehemu','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Toleo la Lingua Forge, WordPress, na PHP; mandhari hai; muundo wa URL; lugha ya tovuti ya WP na lugha kuu ya maudhui. Ishara nyekundu karibu na lugha ya tovuti ya WP ina maana si mojawapo ya lugha za maudhui zinazofuatwa — irekebishe katika Mipangilio → Jumla kabla ya kitu kingine.','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Mtoa huduma hai, funguo zilizowekwa, chaguo za kiwango cha mfano, preset, na kikomo cha kila siku.','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Inathibitisha kuwa muundo wa permalink unalingana na njia ya Lingua Forge. Miundo rahisi na ile ya nambari pekee haijaungwa mkono.','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Orodhesha programu-jalizi zozote za SEO za watu wa tatu zinazofanya kazi. Lingua Forge huendana na matokeo yake wakati hizi zipo — angalia Mipangilio → SEO → Ulinganifu kwa uchambuzi wa kila kipengele.','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'Toleo la WooCommerce, hali ya uhifadhi wa oda (CPT / HPOS / shared), na jedwali la ufunuo wa tafsiri kwa lugha kwa kurasa nne za ndani za WC (Duka, Mchango, Malipo, Akaunti Yangu).','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Orodhesha aina za machapisho ambazo zimechapisha machapisho bila thamani ya meta _lf_lang. Machapisho yanayokosa lebo hii hayana mwonekano kwa vichujio vyote vya lugha. Tumia kitufe cha Rejesha kuziweka lebo kwa lugha ya chanzo, au Epuka kuondoa aina ya chapisho kutoka kwa mwelekeo wa lugha kabisa.','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'Utoaji wa data unaoweza kusukumwa wa vitu vyote vinavyomilikiwa na LF katika $wp_rewrite->extra_rules_top. Inafaa kwa kugundua 404 au migogoro ya mwelekeo baada ya kuongeza lugha mpya.','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Nakili kwa kubofya mara moja muhtasari wa mfumo wa maandishi rahisi unaoshughulikia sehemu zote zilizotangulia. Bandika hii kwenye tatizo la GitHub au ombi la msaada ili mazingira yote yaonekane kwa urahisi.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Umegundua hitilafu au tabia isiyotarajiwa? Tafadhali fungua tatizo kwenye GitHub — jumuisha sehemu ya Debug Info hapo juu na maelezo mafupi ya kile ulichotarajia dhidi ya kilichotokea.','Open an issue →'=>'Fungua tatizo →','Getting started'=>'Anza','Server setup (subdomain)'=>'Mipangilio ya seva (subdomain)','Translation workflow'=>'Mchakato wa Tafsiri','Language switcher'=>'Kisakinishi cha Lugha','WP-CLI reference'=>'Rejea ya WP-CLI','Integration API'=>'API ya Uunganisho','Documentation'=>'Nyaraka','Report an issue on GitHub'=>'Ripoti tatizo kwenye GitHub','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','WordPress AI Client (WP 7.0+)'=>'Mteja wa AI wa WordPress (WP 7.0+)','Meta Description, Excerpt Generator'=>'Maelezo ya Meta, Mwandishi wa Muhtasari','Translation, Content Generator'=>'Tafsiri, Mwandishi wa Maudhui','Testing…'=>'Inajaribu…','✓ Connection OK'=>'✓ Muunganisho mzuri','✗ Failed:'=>'✗ Imeshindwa:','No response from provider — check the error log for details.'=>'Hakuna majibu kutoka kwa mtoa huduma — angalia kumbukumbu za makosa kwa maelezo.','Network error — could not reach the WordPress AJAX endpoint.'=>'Hitilafu ya mtandao — haikuweza kufikia mwisho wa AJAX wa WordPress.','Translating a real post with this model…'=>'Kutafsiri chachu halisi kwa mtindo huu…','preset'=>'preset','Loading…'=>'Inapakia…','Installing…'=>'Inasakinishwa…','✓ Language installed.'=>'✓ Lugha imewekwa.','✗ Error:'=>'✗ Hitilafu:','Creating…'=>'Inaundwa…','✓ All templates created.'=>'✓ Kila kiolezo kimeundwa.','Some templates could not be created.'=>'Baadhi ya kiolezo hakikuweza kuundwa.','Recreating…'=>'Kutengeneza upya…','✓ All templates recreated.'=>'✓ Violezo vyote vimetengenuliwa.','Some templates could not be recreated.'=>'Violezo vingine havikuweza kutengenezwa.','This overwrites this template with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Hii inabadilisha violezo hivi na nakala mpya safi kutoka kwa mandharinyuma yenye umeme, ikitupilia mbegu uzalishaji wa Mhariri wa Tovuti uliotengenezwa. Hii haiwezi kutengenezwa. Kuendelea?','This overwrites every template with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Hii inabadilisha violezo vyote na nakala mpya safi kutoka kwa mandharinyuma yenye umeme, ikitupilia mbegu uzalishaji wa Mhariri wa Tovuti uliotengenezwa. Hii haiwezi kutengenezwa. Kuendelea?','✓ All parts recreated.'=>'✓ Sehemu zote zimefanywa upya.','Some parts could not be recreated.'=>'Sehemu zingine hazikuweza kufanywa upya.','This overwrites this template part with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Hii inabadilisha sehemu hii ya violezo na nakala mpya safi kutoka kwa mandharinyuma yenye umeme, ikitupilia mbegu uzalishaji wa Mhariri wa Tovuti uliotengenezwa. Hii haiwezi kutengenezwa. Kuendelea?','This overwrites every template part with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Hii inabadilisha sehemu zote za violezo na nakala mpya safi kutoka kwa mandharinyuma yenye umeme, ikitupilia mbegu uzalishaji wa Mhariri wa Tovuti uliotengenezwa. Hii haiwezi kutengenezwa. Kuendelea?','✓ All parts created.'=>'✓ Sehemu zote zimetengenezwa.','Some parts could not be created.'=>'Sehemu zingine hazikuweza kuundwa.','✓ All translated.'=>'✓ Zote zimefasirishwa.','Some translations failed.'=>'Baadhi ya tafsiri zimeshindwa.','Review carefully — links and slugs not updated.'=>'Kagua kwa makini — viungo na slugs havijasasishwa.','Fixing…'=>'Inarekebishwa…','✓ Links fixed.'=>'✓ Viungo vimerekebishwa.','Some link fixes failed.'=>'Baadhi ya marekebisho ya viungo yameshindwa.','✓ Parts fixed.'=>'✓ Sehemu zimerekebishwa.','Some part fixes failed.'=>'Sehemu zingine hazikuweza kurekebishwa.','✓ Nav refs fixed.'=>'✓ Marejeo ya urambazaji yamerekebishwa.','Some nav ref fixes failed.'=>'Marekebisho ya marejeo ya urambazaji yameshindwa.','✓ Pattern translated.'=>'✓ Mfano umefasirishwa.','Pattern translation failed.'=>'Ufasirishwa kwa mfano umeshindwa.','Hide'=>'Ficha','Re-create all templates'=>'Tengeneza upya violezo vyote','Re-create all parts'=>'Tengeneza upya sehemu zote','This runs Re-create all templates, Re-create all parts, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time. It overwrites existing templates and parts with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template and part, which may take a while and may incur cost depending on your provider. Continue?'=>'Hii inatumia Tengeneza upya violezo vyote, Tengeneza upya sehemu zote, Tafsiri zote, Rekebisha sehemu zote, na Rekebisha viungo vyote kwa kila lugha yenye umeme ya {total}, moja moja. Inabadilisha violezo na sehemu zilizopo na nakala mpya safi kutoka kwa mandharinyuma yenye umeme (ikitupilia mbegu uzalishaji wa Mhariri wa Tovuti) na kutafsiri upya maudhui — kila kitu hiki hakiwezi kutengenezwa. Tafsiri zote inafanya simu halisi za AI API kwa kila violezo na sehemu, ambayo inaweza kuchukua muda na inaweza kusambaza gharama kulingana na mtoa huduma wako. Kuendelea?','This runs Re-create all templates, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time — template parts (headers, footers, etc.) are left untouched. It overwrites existing templates with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template, which may take a while and may incur cost depending on your provider. Continue?'=>'Hii inatumia Tengeneza upya violezo vyote, Tafsiri zote, Rekebisha sehemu zote, na Rekebisha viungo vyote kwa kila lugha yenye umeme ya {total}, moja moja — sehemu za violezo (vichwa, pambio, nk) zimeasadiwa sema sio zilizobadilishwa. Inabadilisha violezo zilizopo na nakala mpya safi kutoka kwa mandharinyuma yenye umeme (ikitupilia mbegu uzalishaji wa Mhariri wa Tovuti) na kutafsiri upya maudhui — kila kitu hiki hakiwezi kutengenezwa. Tafsiri zote inafanya simu halisi za AI API kwa kila violezo, ambayo inaweza kuchukua muda na inaweza kusambaza gharama kulingana na mtoa huduma wako. Kuendelea?','This runs Re-create all parts (headers, footers, and every other template part) for every one of your {total} active languages, one language at a time. It overwrites existing template parts with fresh copies from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Hii inatumia Tengeneza upya sehemu zote (vichwa, pambio, na sehemu nyingine yote za violezo) kwa kila lugha yenye umeme ya {total}, moja moja. Inabadilisha sehemu za violezo zilizopo na nakala mpya safi kutoka kwa mandharinyuma yenye umeme, ikitupilia mbegu uzalishaji wa Mhariri wa Tovuti uliotengenezwa. Hii haiwezi kutengenezwa. Kuendelea?','Starting…'=>'Kuanza…','Processing {lang} ({index} of {total}) — {step}…'=>'Ikusanya {lang} ({index} ya {total}) — {step}…','Cancelled.'=>'Ilisitishwa.','{done} of {total} languages processed.'=>'{done} ya lugha za {total} ziliikusanya.','⚠ Done with issues.'=>'⚠ Kumalizika na matatizo.','✓ All {total} languages processed.'=>'✓ Lugha zote za {total} zilikusanya.','Built-in preset instructions:'=>'Maagizo ya awali yaliyowekwa ndani:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Hakuna maagizo yaliyowekwa ndani — kila kipengele cha AI kinatumia chaguo zake zilizobinafsishwa. Jaza uwanja wa Maagizo ya Maelekezo ya Maoni ya Kibinafsi hapa chini ili kuongeza kanuni zako za tovuti kwa ujumla.','Modified'=>'Imebadilishwa','edit'=>'hariri','No published posts found for the selected filters.'=>'Hakuna machapisho yaliyochapwa yaliyopatikana kwa vichujio vilivyoteuliwa.','Just now'=>'Sasa hivi','Score'=>'Alama','Source title'=>'Kichwa cha chanzo','Multilingual SEO overview'=>'Muhtasari wa SEO ya Lugha Nyingi','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Alama ni ishara, si hukumu. Baadhi ya maudhui yana mipaka ya muundo — kurasa fupi sana, kurasa za kutua zenye maudhui machache, au kurasa zinazolenga urambazaji kuliko taarifa zinaweza kuwa na alama za chini kwa asili. Tumia muhtasari huu kubaini pengo halali la usawa kati ya lugha, si kufuata nambari.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Hii ni ukurasa wa mfumo wa WooCommerce (Duka, Mzigo, Malipo, n.k.). Yaliyomo yanashughulikiwa na WooCommerce — alama inaonyesha tu ishara za muundo, si maudhui ya SEO yanayoweza kuhaririwa na mtumiaji.','Settings'=>'Mipangilio','You do not have permission to manage these settings.'=>'Huna ruhusa ya kusimamia mipangilio hii.','Lingua Forge — Settings'=>'Lingua Forge — Mipangilio','Settings saved.'=>'Mipangilio imehifadhiwa.','Save Settings'=>'Hifadhi Mipangilio','Standard'=>'Kawaida','Technical / Scientific'=>'Kitaaluma / Sayansi','Legal / Compliance'=>'Kisheria / Uzingatiaji','Creative / Marketing'=>'Ubunifu / Masoko','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — Takwimu za Matumizi ya AI','Lingua Forge AI Usage Statistics'=>'Takwimu za Matumizi ya Lingua Forge AI','Date'=>'Tarehe','Request count'=>'Idadi ya maombi','Full Article'=>'Makala Kamili','Introduction only'=>'Utangulizi tu','Structured Outline'=>'Muhtasari wa Muundo','Generate Content'=>'Tengeneza Yaliyomo','Hints'=>'Vidokezo','Key points, ideas, or structure to build from…'=>'Vitu muhimu, mawazo, au muundo wa kujenga kutoka...','Tone'=>'Mwelekeo','Output'=>'Matokeo','Generate Excerpt'=>'Unda Kipengele','Generate Meta Description'=>'Unda Maelezo Meta','Translate Content'=>'Tafsiri Maudhui','Mode'=>'Hali','Full post'=>'Ujumbe kamili','Translate chunk'=>'Tafsiri sehemu','Target Language'=>'Lugha inayolengwa','Text to translate'=>'Maandishi ya kutafsiri','Paste a footnote, sentence, or any snippet here…'=>'Bandika nukuu ya mguu wa ukurasa, sentensi, au kipande chochote hapa...','Also generate meta description'=>'Pia tengeneza maelezo meta','Translated Labels'=>'Vitu vinavyoashiriwa vya Tafsiri','Attribute label displayed in this language. Leave empty to use the default label.'=>'Lebo ya sifa inayoonyeshwa kwa lugha hii. Acha tupu ili kutumia lebo chaguo-msingi.','Translate all labels (AI)'=>'Tafsiri lebo zote (AI)','Insufficient permissions.'=>'Ruhusa hazitoshi.','All labels already translated.'=>'Lebo zote tayari zimeletwa.','%d label(s) translated.'=>'%d lebo(zo) zilizotafsiriwa.','Translation failed. Check the browser console.'=>'Tafsiri imekosekana. Angalia konsoli ya kivinjari.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Haiwezi kuandika kwa bidhaa %1$d: ni toleo lililotafsiriwa (lugha: %2$s)%3$s. Data ya kiutendaji (bei, hisa, SKU, vipimo) inapaswa kusasishwa kwenye bidhaa chanzo. Suluhisha ID ya bidhaa chanzo kupitia: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Translated Names'=>'Majina yaliyotafsiriwa','Name displayed in this language. Leave empty to use the source name.'=>'Jina linaloonyeshwa kwa lugha hii. Acha tupu ili kutumia jina la chanzo.','Translate all tags (AI)'=>'Tafsiri alama zote (AI)','Translate all categories (AI)'=>'Tafsiri kategoria zote (AI)','Translate all %s terms (AI)'=>'Tafsiri maneno yote %s (AI)','Translate all terms (AI)'=>'Tafsiri maneno yote (AI)','Invalid taxonomy.'=>'Aina ya uainishaji si sahihi.','No terms found.'=>'Hakuna maneno yaliyopatikana.','%d term(s) translated.'=>'%d neno(neno) zilizotafsiriwa.','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d tayari imetafsiriwa — <a href="#" class="lf-force-translate">lazima utafsiri tena</a>','%1$d translated, %2$d skipped.'=>'%1$d zilizotafsiriwa, %2$d zilizorukwa.','Order placed in language: %s'=>'Agizo lililofanywa katika lugha: %s','Invalid API key — double-check the key entered in the AI Provider settings.'=>'Ufunguo wa API usio sahihi — hakikisha uangalie kwa makini ufunguo ulioingizwa katika mipangilio ya Mtoa Huduma wa AI.','Payment required — your account has no remaining credits.'=>'Malipo yanahitajika — akaunti yako haina salio la ziada.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Ruhusa imezuiwa — akaunti yako inaweza kusimamishwa au ufunguo haujapata ruhusa zinazohitajika.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Imezuiwa kwa kiwango cha juu — maombi mengi sana yamepelekwa kwa mtoa huduma; subiri kidogo na jaribu tena.','Provider service temporarily unavailable — try again in a moment.'=>'Huduma ya mtoa huduma kwa muda haipatikani — jaribu tena baada ya muda.','Provider error (HTTP %1$d): %2$s'=>'Hitilafu ya mtoa huduma (HTTP %1$d): %2$s','Unexpected provider error (HTTP %d).'=>'Hitilafu isiyotarajiwa ya mtoa huduma (HTTP %d).','No API key configured — enter your key in the AI Provider settings.'=>'Hakuna ufunguo wa API uliowekwa — ingiza ufunguo wako katika mipangilio ya Mtoa Huduma wa AI.','Network error — could not reach the provider: %s'=>'Hitilafu ya mtandao — haikuweza kufikia mtoa huduma: %s','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'Hakuna salio linalobaki — ongeza salio la akaunti yako ya OpenAI kwenye platform.openai.com/account/billing.','WordPress AI Client requires WordPress 7.0 or later.'=>'Mteja wa AI wa WordPress unahitaji WordPress 7.0 au zaidi.','No user message found in the message array.'=>'Hakuna ujumbe wa mtumiaji uliopatikana katika safu ya ujumbe.','No text-generation model is available. Configure an AI provider in Settings → Connectors.'=>'Hakuna mfano wa kuunda maandishi upatikanaji. Sanidi mtoa huduma wa AI katika Settings → Connectors.','Too many AI requests. Please retry in %d seconds.'=>'Orodha nyingi za AI. Tafadhali jaribu tena kwa sekunde %d.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Kiwango cha AI cha kila siku kimefikia (%1$d maombi). Kinarejeshwa saa %2$s UTC.','View Lingua Forge details'=>'Tazama maelezo ya Lingua Forge','View details'=>'Tazama maelezo','Visit plugin site'=>'Tembelea tovuti ya programu-jalizi','Lingua Forge update blocked: download host "%s" is not on the allowlist.'=>'Sasisho la Lingua Forge limezuiwa: mwenyeji wa kupakua "%s" si kwenye orodha ya ruhusa.','Lingua Forge update blocked: SHA-256 of the downloaded package does not match the manifest. The file may have been tampered with.'=>'Sasisho la Lingua Forge limezuiwa: SHA-256 ya kifurushi kilichopakuliwa haifanani na orodha. Faili linaweza kuwa limebadilishwa.','Exclude from navigation menus'=>'Epuka kwenye menyu za urambazaji','Apply to all language versions'=>'Tumia kwa toleo zote za lugha','Lang'=>'Lugha','Also mirrored to: %s'=>'Pia inakarabati kwa: %s','Filter by language'=>'Chuja kwa lugha','All languages'=>'Lugha zote','Noindex (hide this language version from search engines)'=>'Noindex (ficha toleo hili la lugha kutoka kwa injini za utafutaji)','%d language not yet linked'=>'Lugha %d bado haijaundwa' . "\0" . 'Lugha %d bado hazijaundwa','This is the source page. Footnotes are edited directly in the block editor.'=>'Hii ni ukurasa wa chanzo. Nukuu za mguu wa ukurasa huhaririwa moja kwa moja kwenye mhariri wa vikundi.','No source page linked yet.'=>'Bado hakuna ukurasa wa chanzo umeunganishwa.','The source page has no footnotes.'=>'Ukurasa wa chanzo haujakuwa na nukuu za mguu wa ukurasa.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Nukuu hizi za mguu wa ukurasa zinatoka kwenye ukurasa wa chanzo na zinaonyeshwa hapa kwa marejeo tu. Ziongeze kwenye ukurasa huu kwa kutumia mhariri wa vikundi.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d kiolezo zilizotafsiriwa kutoka kwa mandhari &#8220;%2$s&#8221; zimehifadhiwa kwenye hifadhidata lakini kwa sasa hazifanyi kazi. Zitatumika tena ikiwa utarejesha hali ya mandhari hiyo. Ili kuhamisha tafsiri zako kwa mandhari mpya, zitengeneze tena kupitia <strong>Mipangilio → Lingua Forge → Router → FSE scaffold</strong>.','Scanning posts for missing or out-of-sync featured images…'=>'Inatafuta machapisho yanayokosa au isiyo sawa na picha za kichwa…','Re-scanning…'=>'Inasoma tena...','Scan failed: '=>'Uchunguzi umeshindwa: ','unknown error'=>'hitilafu isiyojulikana','Scan request failed. Please try again.'=>'Ombi la uchunguzi limekosa mafanikio. Tafadhali jaribu tena.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Hakuna machapisho 